function esc(s){ return (s==null?'':String(s)).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

// Construit une image avec repli automatique : le degrade + glyphe reste toujours en
// dessous, et l'<img> par-dessus se cache proprement (onerror) si l'URL est cassee/expiree,
// au lieu de laisser un cadre vide comme auparavant.
function imgWithFallback(url, fallbackUrl, alt){
  if (!url) return '';
  return '<img src="'+esc(url)+'" loading="lazy" decoding="async" alt="'+esc(alt||'')+'" '
    + (fallbackUrl ? ('data-fb="'+esc(fallbackUrl)+'" ') : '')
    + 'style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover" '
    + 'onerror="var f=(this.getAttribute(\'data-fb\')||\'\').split(\'|\'),n=f.shift();this.setAttribute(\'data-fb\',f.join(\'|\'));if(n){this.src=n;}else{this.onerror=null;this.style.display=\'none\';}">';
}
function posterHtml(item, big){
  var img = resolvePosterUrl(item.id);
  var pal=paletteFor(item.id), g=glyphFor(item.id);
  return '<div class="t-poster" style="background:linear-gradient(155deg,'+pal[0]+'55,'+pal[1]+' 75%)">'
    + '<div class="glyph">'+g+'</div>'
    + imgWithFallback(img, '', 'Affiche : '+item.title)
    + (big ? '' : '') + '</div>';
}
function smallPosterHtml(item){
  var img = resolvePosterUrl(item.id);
  return '<div class="v-poster"><div class="glyph">'+glyphFor(item.id)+'</div>'+imgWithFallback(img, '', 'Affiche : '+item.title)+'</div>';
}
