function resolvePosterUrl(id){
  if (!id) return '';
  if (POSTER_IMAGES[id]) return POSTER_IMAGES[id];
  if (typeof CUSTOM_IMAGES !== 'undefined' && CUSTOM_IMAGES[id]) return CUSTOM_IMAGES[id];
  return 'https://maerongrieshaber-a11y.github.io/mcu-images-/posters/poster_' + id + '.jpg';   // affiche deposee plus tard sur GitHub : s'affiche automatiquement
}

function phaseColor(p){ var h=(typeof BG_HUE!=='undefined' && BG_HUE[p]!==undefined) ? BG_HUE[p] : 0; return 'hsl('+(((270+h)%360+360)%360)+',80%,72%)'; }
function sagaColorForPhase(phaseId){
  var p = PHASES.filter(function(x){return x.id===phaseId;})[0];
  return SAGAS[p.saga].color;
}

