// pour un contenu deja present dans la timeline mais pas encore sorti : un compte a rebours
// dynamique s'affichera automatiquement sur sa fiche detaillee. Laisse la valeur vide ('')
// tant que la date n'est pas confirmee : un badge "Date à confirmer" s'affiche a la place.
var RELEASE_DATES = {
  '': '',   // Spider-Man: Brand New Day (2026)
  '': '',   // Daredevil: Born Again — Saison 2 (2026)
};

// Projets annonces mais pas encore integres a la timeline officielle (metadonnees encore
// incompletes). C'est TOI qui ajoutes une ligne ici a la main, pas le visiteur du site.
// Champs : id (unique), title, type ('Film' ou 'Série'), year (annee prevue).
// releaseDate est optionnel ('YYYY-MM-DD') ; laisse '' tant que la date exacte n'est pas
// connue, un compte a rebours dynamique apparaitra automatiquement des qu'elle est remplie.
// Pour lui donner une affiche, ajoute une entree avec ce meme id dans POSTER_IMAGES / HERO_IMAGES.
var UPCOMING_ITEMS_RAW = [
  // Exemple de canevas vide a dupliquer :
  // { id:'mon-id-unique', title:'Titre', type:'Film', year:2027, releaseDate:'', summary:'' },

  { id:'avengers-doomsday', title:'Avengers: Doomsday', type:'Film', year:2026, releaseDate:'2026-12-16',   // date France (aux Etats-Unis : 18 decembre 2026)
    summary:"Le grand crossover des Avengers : Robert Downey Jr. y joue Victor von Doom, nouvelle menace qui remplace Kang après l'abandon de The Kang Dynasty. Sortie le 16 décembre 2026 en France (18 décembre aux États-Unis). Suite : Avengers: Secret Wars." },

  { id:'avengers-secret-wars', title:'Avengers: Secret Wars', type:'Film', year:2027, releaseDate:'2027-12-15',   // date France (aux Etats-Unis : 17 decembre 2027)
    summary:"Conclusion de la Multiverse Saga, réalisée par Anthony et Joe Russo et inspirée des comics Secret Wars de Jim Shooter. Sortie le 15 décembre 2027 en France (17 décembre aux États-Unis)." },

];
var UPCOMING_ITEMS = UPCOMING_ITEMS_RAW.map(function(u){
  var o = {}; for (var k in u) { o[k]=u[k]; }
  o.upcoming = true;
  return o;
});

function isUpcoming(id){
  return RELEASE_DATES.hasOwnProperty(id) || UPCOMING_ITEMS.some(function(u){ return u.id===id; });
}

function fmtCountdown(ms){
  if (ms<=0) return 'Disponible !';
  var s=Math.floor(ms/1000);
  var d=Math.floor(s/86400); s-=d*86400;
  var h=Math.floor(s/3600); s-=h*3600;
  var m=Math.floor(s/60); s-=m*60;
  return d+'j '+String(h).padStart(2,'0')+'h '+String(m).padStart(2,'0')+'m '+String(s).padStart(2,'0')+'s';
}
// Badge/compte a rebours pour un contenu a venir. Si aucune date precise n'est encore
// connue, affiche un badge sobre "Date à confirmer" ; sinon, un compte a rebours vivant.
function countdownBadgeHtml(dateStr){
  if (!dateStr) {
    return '<span class="badge mono" style="border-color:#5B6FE8;color:#8B9BFF">\u23F3 Date à confirmer</span>';
  }
  return '<span class="badge mono mcu-countdown" data-countdown="'+esc(dateStr)+'" style="border-color:#5B6FE8;color:#8B9BFF">--</span>';
}
// Met a jour tous les comptes a rebours visibles a l'ecran sans re-rendre toute l'app
// (appele chaque seconde + juste apres chaque rendu, pour rester exact des l'affichage).
function tickCountdowns(){
  var now = Date.now();
  var nodes = document.querySelectorAll('#mcu-app [data-countdown]');
  for (var i=0; i<nodes.length; i++) {
    var el = nodes[i];
    var raw = el.getAttribute('data-countdown');
    var t = raw ? new Date(raw).getTime() : NaN;
    el.textContent = isNaN(t) ? 'Date à confirmer' : ('\u23F3 '+fmtCountdown(t-now));
  }
}
setInterval(tickCountdowns, 1000);

