var quizState = {};

function getQuizState(id){
  if(!quizState[id]) quizState[id] = { idx: 0, score: 0, answered: null, started: false, finished: false, questions: QUIZZES[id] };
  return quizState[id];
}
// Melange les options de chaque question (et ajuste l'index de la bonne reponse en
// consequence), pour qu'un visiteur ne puisse jamais deviner en retenant juste une
// position. Refait a chaque lancement ET relance du quiz.
function shuffleQuizQuestions(questions){
  return questions.map(function(q){
    var order = q.options.map(function(_, i){ return i; });
    for (var i = order.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = order[i]; order[i] = order[j]; order[j] = tmp;
    }
    return { q: q.q, diff: q.diff, options: order.map(function(i){ return q.options[i]; }), correct: order.indexOf(q.correct) };
  });
}

function renderQuizSection(id){
  var baseQuestions = QUIZZES[id];
  if(!baseQuestions || !baseQuestions.length) return '';
  var qs = getQuizState(id);
  var questions = qs.questions;   // version melangee en cours (ou l'originale si pas encore lance)
  var already = !!state.quizPerfect[id];
  var html = '<h2 class="disp" style="color:#E8C468;font-size:22px;margin:24px 0 10px;display:flex;align-items:center;gap:8px">\uD83C\uDFC6 Quiz <span style="font-size:12px;color:#C9A24B;font-family:\'JetBrains Mono\',monospace;letter-spacing:0.05em">+'+QUIZ_XP_BONUS+' XP</span></h2>';

  if(!qs.started){
    html += '<div class="card" style="border-color:#C9A24B;background:linear-gradient(120deg,rgba(201,162,75,0.14),rgba(232,84,107,0.05));display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;padding:18px">'
      + '<div><div style="font-size:14px;color:#EDEAE3;font-weight:600">'+baseQuestions.length+' question(s) sur ce contenu</div>'
      + '<div style="font-size:12px;color:#B7B2AA;margin-top:2px">'+(already ? '\u2705 Déjà réussi sans faute : rejoue pour le plaisir !' : 'Score parfait = +'+QUIZ_XP_BONUS+' XP bonus \uD83C\uDF89')+'</div></div>'
      + '<button class="btn-cta" style="padding:10px 22px;font-size:13px" onclick="mcuQuizStart(\''+id+'\')">'+(already?'Rejouer':'Lancer le quiz')+'</button>'
      + '</div>';
    return html;
  }

  if(qs.finished){
    var perfect = qs.score === questions.length;
    html += '<div class="card" style="text-align:center;'+(perfect?'border-color:#C9A24B;background:linear-gradient(160deg,rgba(201,162,75,0.16),transparent)':'')+'">'
      + (perfect ? '<div style="font-size:34px;margin-bottom:4px">\uD83C\uDFC6</div>' : '')
      + '<div class="disp" style="font-size:28px;color:#E8C468">'+qs.score+' / '+questions.length+'</div>'
      + '<div style="font-size:13px;color:#B7B2AA;margin:6px 0 12px">'+(perfect ? 'Score parfait'+(already?' !':' - +'+QUIZ_XP_BONUS+' XP gagnes !') : 'bonnes reponses')+'</div>'
      + '<button class="btn" onclick="mcuQuizStart(\''+id+'\')">Recommencer</button>'
      + '</div>';
    return html;
  }

  var q = questions[qs.idx];
  var isLastQuestion = qs.idx === questions.length - 1;
  var diffLabels = { easy:{label:'Facile',color:'#4CD98A'}, medium:{label:'Moyen',color:'#E8C468'}, hard:{label:'Difficile',color:'#E8546B'} };
  var diffInfo = diffLabels[q.diff];
  html += '<div class="card" style="border-color:#3A3640">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">'
    + '<span style="font-size:11px;color:#9AA0AA">Question '+(qs.idx+1)+' / '+questions.length+'</span>'
    + (diffInfo ? '<span class="mono" style="font-size:10px;padding:2px 9px;border-radius:999px;border:1px solid '+diffInfo.color+';color:'+diffInfo.color+'">'+diffInfo.label+'</span>' : '')
    + '</div>'
    + '<div style="font-size:15px;margin-bottom:14px">'+esc(q.q)+'</div>'
    + '<div style="display:flex;flex-direction:column;gap:8px">';
  q.options.forEach(function(opt, i){
    var style = 'text-align:left;padding:10px 14px;border-radius:8px;border:1px solid #3A3640;';
    if(qs.answered!=null){
      if(i===q.correct) style += 'border-color:#2E7D5B;background:rgba(46,125,91,0.15);color:#4CD98A;';
      else if(i===qs.answered) style += 'border-color:#E8546B;background:rgba(232,84,107,0.12);color:#E8546B;';
    }
    html += '<button style="'+style+'" onclick="mcuQuizAnswer(\''+id+'\','+i+')" '+(qs.answered!=null?'disabled':'')+'>'+esc(opt)+'</button>';
  });
  html += '</div>';
  if(qs.answered!=null){
    // Sur la derniere question, la fin (score + recompense) s'affiche automatiquement
    // apres un court delai (voir mcuQuizAnswer) - pas besoin de bouton supplementaire.
    if (!isLastQuestion) {
      html += '<button class="btn" style="margin-top:14px" onclick="mcuQuizNext(\''+id+'\')">Question suivante</button>';
    } else {
      html += '<div style="margin-top:14px;font-size:12px;color:#8A8690;text-align:center">Calcul du score\u2026</div>';
    }
  }
  html += '</div>';
  return html;
}

window.mcuQuizStart=function(id){
  packCoverLoad();   // prechauffe la cover du paquet (elle n'est plus chargee au demarrage du site)
  quizState[id] = { idx:0, score:0, answered:null, started:true, finished:false, questions: shuffleQuizQuestions(QUIZZES[id]) };
  renderModal();
};
window.mcuQuizAnswer=function(id, i){
  var qs = getQuizState(id);
  if(qs.answered!=null) return;
  qs.answered = i;
  if (qs.questions[qs.idx].correct === i) qs.score++;
  var isLast = qs.idx === qs.questions.length - 1;
  renderModal();
  if (isLast) {
    // Laisse voir brievement la bonne/mauvaise reponse en surbrillance avant d'enchainer
    // automatiquement sur l'ecran de score + recompense (plus besoin de cliquer).
    setTimeout(function(){ finishQuiz(id); }, 1100);
  }
};
function finishQuiz(id){
  var qs = getQuizState(id);
  if (qs.finished) return;
  qs.finished = true;
  var questions = qs.questions;
  // Recompense uniquement la toute premiere fois qu'un quiz est reussi SANS FAUTE
  // (rejouer ne fait pas regagner la recompense, mais reste amusant a refaire).
  if (qs.score === questions.length && !state.quizPerfect[id]) {
    var rankBefore = quizRankFor(quizPerfectCount(state));
    var newlyEarned = ACHIEVEMENTS.filter(function(a){ return !state.seenAchievements[a.id]; });
    state.quizPerfect[id] = true;

    // Debloque les cartes liees a ce contenu uniquement apres un score parfait.
    // Toutes les nouvelles cartes du meme quiz sont regroupees dans un seul paquet.
    var newCards = CARDS
      .filter(function(c){ return c.unlock === id && cardIsUnlocked(c) && !state.seenCards[c.id]; })
      .map(function(c){ return c.id; });
    newCards.forEach(function(cid){ state.seenCards[cid] = true; });

    saveState(state);
    var rankAfter = quizRankFor(quizPerfectCount(state));
    var stillNew = newlyEarned.filter(function(a){ return a.check(state) && !state.seenAchievements[a.id]; });
    stillNew.forEach(function(a){ state.seenAchievements[a.id] = true; });
    saveState(state);
    if (rankAfter.name !== rankBefore.name) {
      // Montee de rang : la vraie recompense, mise en avant plutot qu'un simple chiffre d'XP.
      showToast(rankAfter.icon, 'NOUVEAU RANG DE QUIZ', rankAfter.name, 'Voir ton rang sur ton profil !');
    } else {
      showToast('\u2728', 'QUIZ REUSSI !', 'Score parfait +'+QUIZ_XP_BONUS+' XP', rankAfter.count+' quiz parfait(s) \u2014 '+rankAfter.name);
    }
    stillNew.forEach(function(a, i){ setTimeout(function(){ showAchievementToast(a); }, 900+i*550); });
    if (newCards.length) {
      setTimeout(function(){ showPack(newCards); }, 700);
    }
  }
  renderModal();
}
window.mcuQuizNext=function(id){
  var qs = getQuizState(id);
  var questions = qs.questions;
  if(qs.idx < questions.length-1){ qs.idx++; qs.answered=null; renderModal(); }
  else { finishQuiz(id); }
};

