// ---------------------------------------------------------------------------------------
// BARRE DE RECHERCHE : suggestions live (autocompletion) + bouton pour vider le champ.
// Cherche a la fois dans les contenus (films/series/specials, MCU + Hors MCU + a venir) et
// dans les personnages, pour qu'ecrire "i" propose par exemple "Iron Man" ET "Iron Fist".
// ---------------------------------------------------------------------------------------
function searchSuggestions(query){
  query = (query||'').trim().toLowerCase();
  if (!query) return [];
  var out = [];
  ITEMS.concat(OTHER).concat(UPCOMING_ITEMS).forEach(function(it){
    if (it.title.toLowerCase().indexOf(query)!==-1) {
      out.push({ id: it.id, kind:'media', title: it.title, sub: it.type + (it.year?(' \u00B7 '+it.year):'') });
    }
  });
  CHARS.forEach(function(ch){
    if (ch.name.toLowerCase().indexOf(query)!==-1) {
      out.push({ id: ch.id, kind:'character', title: ch.name, sub:'Personnage' });
    }
  });
  // Priorite aux resultats qui COMMENCENT par la recherche, puis ordre alphabetique.
  out.sort(function(a,b){
    var aStarts = a.title.toLowerCase().indexOf(query)===0 ? 0 : 1;
    var bStarts = b.title.toLowerCase().indexOf(query)===0 ? 0 : 1;
    if (aStarts!==bStarts) return aStarts-bStarts;
    return a.title.localeCompare(b.title);
  });
  return out.slice(0, 6);
}
// Construit un champ de recherche avec bouton "effacer" (croix) et menu de suggestions.
// filterKey: la cle dans l'objet filters (ex: 'query'), showSuggestions: true pour la
// recherche principale (avec autocompletion vers les fiches), false pour une simple recherche
// texte (ex: filtre des cartes a collectionner, qui n'a pas de fiche a ouvrir).
function renderSearchBox(value, focusId, filterKey, placeholder, showSuggestions){
  var html = '<div class="mcu-search-wrap">'
    + '<input data-focus-id="'+focusId+'" placeholder="'+esc(placeholder)+'" value="'+esc(value)+'" oninput="mcuSetFilter(\''+filterKey+'\', this.value)" autocomplete="off">';
  if (value) {
    html += '<button type="button" class="mcu-search-clear" title="Effacer" onclick="mcuClearFilter(\''+filterKey+'\')">\u2715</button>';
  }
  if (showSuggestions && value) {
    var sugg = searchSuggestions(value);
    if (sugg.length) {
      html += '<div class="mcu-suggest">' + sugg.map(function(s){
        return '<button type="button" onmousedown="event.preventDefault();mcuSelectSuggestion(\''+s.id+'\',\''+s.kind+'\',\''+filterKey+'\')">'
          + esc(s.title) + '<span class="mcu-suggest-sub">'+esc(s.sub)+'</span></button>';
      }).join('') + '</div>';
    }
  }
  html += '</div>';
  return html;
}

// ---------------------------------------------------------------------------------------
// PETIT MOT D'ACCUEIL (onboarding) : explique en 4 lignes fun ce qu'on peut faire sur le
// site, une seule fois (ferme avec la croix, ne revient plus jamais ensuite - state.onboardingSeen).
// ---------------------------------------------------------------------------------------
// ---------------------------------------------------------------------------------------
// PROFIL PARTAGEABLE : encode un instantane (pseudo, grade, top contenus, succes) dans
// l'URL elle-meme (comme un lien de partage Spotify) - pas de serveur necessaire, la page
// ouverte par la personne qui recoit le lien lit directement les donnees depuis l'adresse.
// L'avatar (image) reste volontairement local et n'est jamais inclus dans le lien.
// ---------------------------------------------------------------------------------------
function topFavorites(n){
  var favIds = Object.keys(state.favorites).filter(function(k){return state.favorites[k];});
  var favItems = favIds.map(itemById).filter(Boolean);
  if (favItems.length >= n) return favItems.slice(0, n);
  var watchedItems = ITEMS.concat(OTHER).filter(function(i){ return state.watched[i.id] && favIds.indexOf(i.id)===-1; });
  watchedItems.sort(function(a,b){ return (b.rating||0)-(a.rating||0); });
  return favItems.concat(watchedItems).slice(0, n);
}
function b64EncodeUnicode(str){ return btoa(unescape(encodeURIComponent(str))); }
function b64DecodeUnicode(str){ return decodeURIComponent(escape(atob(str))); }
// Petits utilitaires de dessin pour la carte de profil exportable en image (canvas).
function roundRect(ctx, x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x+r, y);
  ctx.arcTo(x+w, y, x+w, y+h, r);
  ctx.arcTo(x+w, y+h, x, y+h, r);
  ctx.arcTo(x, y+h, x, y, r);
  ctx.arcTo(x, y, x+w, y, r);
  ctx.closePath();
}
function wrapText(ctx, text, x, y, maxWidth, lineHeight){
  var words = text.split(' ');
  var line = '';
  for (var i=0; i<words.length; i++){
    var testLine = line + words[i] + ' ';
    if (ctx.measureText(testLine).width > maxWidth && i>0){
      ctx.fillText(line, x, y);
      line = words[i] + ' ';
      y += lineHeight;
    } else {
      line = testLine;
    }
  }
  ctx.fillText(line, x, y);
  return y + lineHeight;
}

function buildShareUrl(){
  var prog = computeProgress(state);
  var topIds = state.profile.topPicks === null ? topFavorites(5).map(function(i){return i.id;}) : (state.profile.topPicks||[]);
  var payload = {
    n: state.profile.name || 'Un fan MCU',
    b: state.profile.bio || '',
    // Pas d'avatar ici : une vraie photo encodee peut faire plusieurs milliers de
    // caracteres, largement au-dela de ce qu'acceptent les DM Instagram (~1000 caracteres)
    // ou les stickers de lien en story. Le lien reste donc volontairement leger et fiable
    // partout (SMS, WhatsApp, Discord...). Pour Instagram/Snapchat, utiliser plutot le
    // bouton "Telecharger l'image" qui genere une vraie image a poster.
    fc: state.profile.favChar || null,
    lvl: prog.level.level, lvlName: prog.level.name, xp: prog.xp,
    ach: prog.earned.length, achTotal: ACHIEVEMENTS.length,
    top: topIds.filter(function(id){ return !!itemById(id); })
  };
  var encoded = b64EncodeUnicode(JSON.stringify(payload));
  return window.location.origin + window.location.pathname + window.location.search + '#mcu-profile=' + encoded;
}
function parseSharedProfileFromHash(){
  var h = window.location.hash || '';
  var idx = h.indexOf('mcu-profile=');
  if (idx === -1) return null;
  try { return JSON.parse(b64DecodeUnicode(h.slice(idx + 'mcu-profile='.length))); }
  catch(e){ return null; }
}
var sharedProfile = parseSharedProfileFromHash();
if (sharedProfile) { view = 'profile'; }

