function statusOk(id){
  var st = filters.status || 'Tous';
  if (st === 'Non vus') return !state.watched[id];
  if (st === 'Vus') return !!state.watched[id];
  return true;
}
function statusSelectHtml(){
  return '<select title="Statut" onchange="mcuSetFilter(\'status\', this.value)">'
    + [['Tous','Tous les statuts'],['Non vus','Non vus'],['Vus','Vus']].map(function(o){ return '<option value="'+o[0]+'" '+((filters.status||'Tous')===o[0]?'selected':'')+'>'+o[1]+'</option>'; }).join('')
    + '</select>';
}
function filteredItems(){
  return ITEMS.filter(function(i){
    if(!statusOk(i.id)) return false;
    if(filters.type!=='Tous' && i.type!==filters.type) return false;
    if(filters.phase!=='Tous' && String(i.phase)!==String(filters.phase)) return false;
    if(filters.query && i.title.toLowerCase().indexOf(filters.query.toLowerCase())===-1) return false;
    return true;
  }).sort(function(a,b){ if(filters.order==='sortie') return (a.year-b.year)||(a.order-b.order); return a.order-b.order;});
}

