function renderScenesBlock(item){
  var n=item.postCredit.count, d=PCS[item.id]||[], seen=(state.scenesSeen||{})[item.id]||[], vus=0, i, h;
  for(i=0;i<n;i++){ if(seen[i]) vus++; }
  h='<h2 class="disp" style="color:#C9A24B;font-size:20px;margin:20px 0 10px">Après le générique</h2>'
   +'<div style="font-size:13px;color:#B7B2AA;margin-bottom:10px">'+n+' scène'+(n>1?'s':'')+' post-générique \u00B7 <span style="color:'+(vus===n?'#4CD98A':'#E8C468')+'">'+vus+'/'+n+' vue'+(vus>1?'s':'')+'</span></div>';
  for(i=0;i<n;i++){
    var sc=d[i], key=item.id+'#'+i, open=sceneShown[key]||seen[i];
    h+='<div class="card" style="margin-bottom:8px;padding:12px;'+(seen[i]?'border-color:#2E7D5B':'')+'">'
     +'<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px"><span class="mono" style="font-size:12px;color:#E8C468">Scène '+(i+1)+(sc?' \u00B7 '+esc(sc[0]):'')+'</span>'
     +'<button class="btn'+(seen[i]?' on-watched':'')+'" onclick="mcuSceneSeen(\''+item.id+'\','+i+')">'+(seen[i]?'\u2713 Vue':'\u2610 Pas vue')+'</button></div>'
     +(open ? '<div style="font-size:13.5px;color:#D8D4CB;line-height:1.5">'+(sc?esc(sc[1]):'<span style="color:#6E7480">Description à venir.</span>')+'</div>'
            : '<button class="btn" onclick="mcuSceneShow(\''+item.id+'\','+i+')">\uD83D\uDC41 Afficher la scène (spoiler)</button>')
     +'</div>';
  }
  return h;
}
window.mcuSceneSeen=function(id,i){
  state.scenesSeen=state.scenesSeen||{}; var a=state.scenesSeen[id]||[]; a[i]=!a[i]; state.scenesSeen[id]=a;
  var newly=ACHIEVEMENTS.filter(function(x){return x.check(state)&&!state.seenAchievements[x.id];}); newly.forEach(function(x){state.seenAchievements[x.id]=true;});
  saveState(state); renderModal();
  newly.forEach(function(x,k){ setTimeout(function(){ showAchievementToast(x); }, k*550); });
};
window.mcuSceneShow=function(id,i){ sceneShown[id+'#'+i]=true; renderModal(); };
