function tourScrollEl(el){
  var r = el.getBoundingClientRect(), vh = window.innerHeight || 800;
  if (r && r.top >= 70 && r.bottom <= vh - 20) { return; }   // déjà bien visible : la page ne bouge pas
  try { el.scrollIntoView({ block: 'center', inline: 'nearest', behavior: 'instant' }); } catch(e){ try { el.scrollIntoView(); } catch(e2){} }
}
function tourSmoothScroll(box, to, ms){
  if (!box) return; var from = box.scrollTop, t0 = Date.now();
  (function stp(){
    var k = Math.min(1, (Date.now() - t0) / ms), e = k < 0.5 ? 2*k*k : 1 - Math.pow(-2*k + 2, 2) / 2;
    box.scrollTop = from + (to - from) * e;
    if (k < 1) { requestAnimationFrame(stp); }
  })();
}
// Fait glisser le quiz dans la fenêtre une seule fois, en douceur : ensuite seul le curseur bouge.
function tourScrollQuiz(){
  var box = tqs('#mcu-modal-root .modal-overlay'), q = tqs('#mcu-modal-root [onclick^="mcuQuizStart("]');
  if (!box || !q) return;
  var card = q.closest ? (q.closest('.card') || q) : q;
  tourSmoothScroll(box, box.scrollTop + card.getBoundingClientRect().top - (window.innerHeight || 800) * 0.12, 800);
}
function tourCursorTo(el, keep){
  if (!el) return false;
  if (!keep) { tourScrollEl(el); }
  var r = el.getBoundingClientRect(), vw = window.innerWidth || 1200, vh = window.innerHeight || 800;
  if (!r || r.width < 6 || r.height < 6 || r.bottom < 0 || r.top > vh || r.right < 0 || r.left > vw) { return false; }
  tourCursorMove(r.left + r.width * 0.5, r.top + r.height * 0.5);
  return true;
}
function tourCursorHide(){ var c = document.getElementById('mcu-tour-cursor'); if (c) { c.style.display = 'none'; } tourCursorReady = false; }
function tourCursorPoint(x, y){ tourCursorMove(x, y); }
function tourClick(el){
  var c = document.getElementById('mcu-tour-cursor');
  if (c && c.classList && tourCursorReady) { c.classList.add('click'); setTimeout(function(){ c.classList.remove('click'); }, 450); }
  if (el && el.click) { el.click(); }
}
var tourSpotTok = 0;
// Met un element en lumiere (si sa position est exploitable) ; element absent ou hors ecran : rien n'est dessine.
function tourSpot(el, pad, keep){
  var s = document.getElementById('mcu-tour-spot'); if (!s) return;
  tourSpotTok++;
  if (!el) { s.style.display = 'none'; return; }
  if (!keep) { tourScrollEl(el); }
  var r = el.getBoundingClientRect(), p = pad == null ? 8 : pad, vw = window.innerWidth || 1200, vh = window.innerHeight || 800;
  if (!r || r.width < 6 || r.height < 6 || r.bottom < 0 || r.top > vh || r.right < 0 || r.left > vw) { s.style.display = 'none'; return; }
  s.style.display = 'block'; s.style.left = Math.round(r.left - p) + 'px'; s.style.top = Math.round(r.top - p) + 'px';
  s.style.width = Math.round(r.width + p*2) + 'px'; s.style.height = Math.round(r.height + p*2) + 'px';
}
function tourSpotRect(x, y, w, hgt){
  var s = document.getElementById('mcu-tour-spot'); if (!s) return;
  tourSpotTok++;
  s.style.display = 'block'; s.style.left = Math.round(x) + 'px'; s.style.top = Math.round(y) + 'px'; s.style.width = Math.round(w) + 'px'; s.style.height = Math.round(hgt) + 'px';
}
function tourHud(show, html, ok){
  var hd = document.getElementById('mcu-tour-hud'); if (!hd) return;
  if (!show) { hd.style.display = 'none'; return; }
  hd.style.display = 'block'; hd.innerHTML = html;
  if (hd.classList) { if (ok) hd.classList.add('ok'); else hd.classList.remove('ok'); }
}
function tourCaptionUpdate(t){
  var idx = -1;
  for (var i=0; i<JARVIS_CAPTIONS.length; i++) { if (t >= JARVIS_CAPTIONS[i][0] && t < JARVIS_CAPTIONS[i][1]) { idx = i; break; } }
  if (idx === tourCapIdx) return;
  tourCapIdx = idx;
  var cap = document.getElementById('mcu-tour-caption'); if (!cap) return;
  if (idx < 0) { if (cap.classList) cap.classList.remove('on'); }
  else { cap.textContent = JARVIS_CAPTIONS[idx][2]; if (cap.classList) cap.classList.add('on'); }
}
function tourTick(){
  if (!tourActive) return;
  var t = tourTime();
  while (tourDone < tourSteps.length && tourSteps[tourDone].at <= t) {
    var st = tourSteps[tourDone++];
    try { st.run(); } catch(e){}
  }
  tourCaptionUpdate(t);
  var pr = document.getElementById('mcu-tour-prog'); if (pr && pr.style) { pr.style.width = Math.min(100, t / JARVIS_TOUR_LENGTH * 100).toFixed(1) + '%'; }
  if (tourVirtual && t > JARVIS_TOUR_LENGTH + 0.5) { tourFinish(); }
}
// Premier contenu (le plus ancien) qui possede un quiz : sert de demonstration.
function tourDemoId(){
  if (QUIZZES['iron-man'] && itemById('iron-man')) { return 'iron-man'; }   // le tuto utilise Iron Man (2008)
  var list = ITEMS.slice().sort(function(a,b){ return a.order - b.order; });
  for (var i=0; i<list.length; i++) { if (QUIZZES[list[i].id] && !list[i].upcoming) { return list[i].id; } }
  return list.length ? list[0].id : null;
}
function tourBuildSteps(){
  var demo = tourDemoId(), S = [];
  var T = function(at, fn){ S.push({ at: at, run: fn }); };
  var tab = function(v){ return tqs('.navtabs button[onclick*="\'' + v + '\'"]'); };
  var poster = function(){ var r = tqs('#mcu-view-root [onclick*="mcuRowClick(\'' + demo + '\')"]'); return r ? (r.querySelector('.v-poster') || r) : null; };
  var toggle = function(){ return tqs('#mcu-modal-root [onclick^="mcuToggleWatched("]'); };
  var qStart = function(){ return tqs('#mcu-modal-root [onclick^="mcuQuizStart("]'); };
  var qNext = function(){ return tqs('#mcu-modal-root [onclick^="mcuQuizNext("]'); };
  var qOpt = function(wrong){
    var qs = quizState[demo], opts = tqsa('#mcu-modal-root [onclick^="mcuQuizAnswer("]');
    var q = (qs && qs.questions) ? qs.questions[qs.idx] : null, ci = q ? q.correct : 0;
    return opts[wrong ? (ci + 1) % (q ? q.options.length : 2) : ci] || null;
  };
  var closeBtn = function(){ return tqs('#mcu-modal-root [onclick="mcuCloseModal()"]'); };
  // Jusqu'au mot "XP" (TOUR_CURSOR_FROM) : pas de curseur, l'element est simplement mis en lumiere 0,9 s avant le clic.
  var actHalo = function(at, getEl){
    T(at - 0.9, function(){ var e = getEl(); if (e) { tourSpot(e, 6); } });
    T(at, function(){ var e = getEl(), tk = tourSpotTok; if (e) { tourClick(e); } setTimeout(function(){ if (tk === tourSpotTok) { tourSpot(null); } }, 380); });
  };
  // A partir du mot "XP" : le curseur glisse vers l'element 0,9 s avant de cliquer.
  var act = function(at, getEl){
    T(at - 0.9, function(){ var e = getEl(); if (e) { tourCursorTo(e); } });
    T(at, function(){ var e = getEl(); if (e) { tourClick(e); } });
  };
  var spot = function(at, getEl, pad){ T(at, function(){ var e = getEl(); if (e) { tourSpot(e, pad); tourCursorTo(e); } }); };
  var off = function(at){ T(at, function(){ tourSpot(null); }); };

  T(0.3, function(){ window.mcuGoto('timeline'); window.scrollTo(0, 0); });
  T(5.0, function(){ tourHud(true, 'PROTOCOLE STARK<br>INITIALISATION\u2026<div class="bar"><i id="mcu-tour-hudbar"></i></div>', false);
    setTimeout(function(){ var b = document.getElementById('mcu-tour-hudbar'); if (b) { b.style.width = '100%'; } }, 60); });
  T(6.6, function(){ tourHud(true, 'PROTOCOLE STARK<br>INITIALISATION TERMIN\u00C9E \u2713', true); });
  T(7.7, function(){ tourHud(false); });
  T(8.0, function(){ var e = tqs('#mcu-view-root .statbar'); if (e) { tourSpot(e, 10); } });   // sans curseur
  off(10.1);
  actHalo(11.8, poster);                                   // sans curseur
  actHalo(14.0, toggle);                                   // sans curseur
  // ---- le curseur apparait ici : mot "XP" (fin de la phrase 10-16 s). Reglage : TOUR_CURSOR_FROM ----
  T(TOUR_CURSOR_FROM, function(){ tourSpot(null); var b = closeBtn(); if (b) { tourCursorTo(b); } });
  T(TOUR_CURSOR_FROM + 0.6, function(){ var b = closeBtn(); if (b) { tourClick(b); } else { window.mcuCloseModal(); } });
  act(18.6, function(){ return tab('characters'); });
  spot(19.8, function(){ return tqs('#mcu-view-root .mcu-card'); }, 6);
  off(22.4);
  act(24.6, function(){ return tab('timeline'); });
  act(25.9, poster);
  var qIdx = function(kind){ var qs = quizState[demo], q = (qs && qs.questions) ? qs.questions[qs.idx] : null; if (!q) return 0; var n = q.options.length, c = q.correct; return kind === 'ok' ? c : (kind === 'bad' ? (c + 1) % n : (c + 2) % n); };
  var qBy = function(kind){ return function(){ return tqsa('#mcu-modal-root [onclick^="mcuQuizAnswer("]')[qIdx(kind)] || null; }; };
  var look = function(at, getEl){ T(at, function(){ var e = getEl(); if (e) { tourCursorTo(e, true); } }); };
  var press = function(at, getEl){ T(at, function(){ var e = getEl(); if (e) { tourClick(e); } }); };
  T(26.6, function(){ tourScrollQuiz(); });                  // un seul glissement doux, puis la page reste fixe
  look(28.3, qStart); press(29.5, qStart);
  look(30.0, qBy('bad')); look(30.8, qBy('ok')); press(31.8, qBy('ok'));
  look(32.1, qNext); press(33.1, qNext);
  look(33.6, qBy('other')); look(34.9, qBy('ok')); look(36.0, qBy('other')); look(36.7, qBy('bad')); press(37.6, qBy('bad'));
  T(38.2, function(){ tourSmoothScroll(tqs('#mcu-modal-root .modal-overlay'), 0, 600); });
  look(38.9, closeBtn);
  T(39.5, function(){ tourSpot(null); delete quizState[demo]; var b = closeBtn(); if (b) { tourClick(b); } else { window.mcuCloseModal(); } });
  act(40.9, function(){ return tab('multiverse'); });
  T(41.2, function(){ window.scrollTo(0, 0); });
  T(41.8, function(){ var e = tqs('#mcu-view-root .hero'); if (e) { tourSpot(e, 12, true); } });
  off(43.5);
  act(44.9, function(){ return tab('horsmcu'); });
  act(47.7, function(){ return tab('journey'); });
  spot(48.8, function(){ return tqs('#mcu-view-root .achv'); }, 8);
  T(50.4, function(){ var w = window.innerWidth || 1200; tourSpotRect(Math.max(8, w - 350), 8, Math.min(340, w - 16), 96); tourCursorPoint(Math.max(40, w - 120), 62); });
  T(50.8, function(){ showToast('\uD83C\uDFC6', 'SUCCÈS DÉBLOQUÉ', 'Exemple de succ\u00E8s', 'Voici \u00E0 quoi ressemblera la notification.'); });
  off(53.0);
  T(53.2, function(){ tourCursorHide(); });
  T(53.4, function(){ tourHud(true, 'TOUS LES SYST\u00C8MES<br>OP\u00C9RATIONNELS \u2713', true); });
  T(55.9, function(){ tourHud(false); tourRestoreState(); window.scrollTo(0, 0); });
  T(57.2, function(){ var bl = document.getElementById('mcu-tour-block'); if (bl && bl.style) { bl.style.display = 'none'; } });
  tourSteps = S.sort(function(a,b){ return a.at - b.at; });
}
function tourRestoreState(){
  if (!tourSnapshot) return;
  Object.keys(state).forEach(function(k){ delete state[k]; });
  Object.keys(tourSnapshot).forEach(function(k){ state[k] = JSON.parse(JSON.stringify(tourSnapshot[k])); });
  tourSnapshot = null; quizState = {};
  currentItemId = null; currentCharId = null; currentCardId = null; currentInfoPanel = null; view = 'timeline';
  renderApp(); renderModal();
}
function tourBuildLayer(){
  var root = document.getElementById('mcu-tour-root'); if (!root) return;
  root.innerHTML = '<div id="mcu-tour-block" class="mcu-tour-block"></div>'
    + '<div class="mcu-tour-top"><i id="mcu-tour-prog"></i></div>'
    + '<button type="button" class="mcu-tour-skip" onclick="mcuTourSkip()">Passer la pr\u00E9sentation \u2715</button>'
    + '<div id="mcu-tour-spot" class="mcu-tour-spot" style="display:none"></div>'
    + '<div id="mcu-tour-hud" class="mcu-tour-hud" style="display:none"></div>'
    + '<div id="mcu-tour-cursor" class="mcu-tour-cursor" style="display:none"><svg width="28" height="28" viewBox="0 0 24 24"><path d="M4 2l16 9-7 2-3 7z" fill="#EAFBFF" stroke="#2aa8ff" stroke-width="1.4" stroke-linejoin="round"/></svg></div>'
    + '<div id="mcu-tour-caption" class="mcu-tour-caption"></div>';
  tourCursorReady = false;
}
function tourFinish(){
  if (!tourActive) return;
  tourActive = false; jarvisStop();
  tourRestoreState(); tourSandbox = false;
  var root = document.getElementById('mcu-tour-root'); if (root) { root.innerHTML = ''; }
  var o = document.getElementById('mcu-orb'); if (o && o.classList) { o.classList.remove('speaking'); }
  musicSetDuck(false);
}
window.mcuTourStart=function(){
  if (tourActive) return;
  selectMode=false; bulkSel={};
  achQueue = []; achStop();
  var root = document.getElementById('mcu-tour-root'); if (root) { root.innerHTML = ''; }
  state.tourSeen = true; saveState(state);                       // enregistre AVANT le bac a sable : la visite ne sera plus proposee d'office
  tourSnapshot = JSON.parse(JSON.stringify(state)); tourSandbox = true; tourActive = true;
  tourDone = 0; tourVirtual = false; tourCapIdx = -1; tourCtx = {};
  quizState = {}; currentItemId = null; currentCharId = null; currentCardId = null; currentInfoPanel = null;
  if (packState) { window.mcuPackClose(); }
  musicSetDuck(true);
  getAudio();                                                    // cree / reveille le contexte audio pendant le clic du visiteur
  tourBuildLayer(); tourBuildSteps();
  jarvisPlay(JARVIS_TOUR_URLS, {
    onend: function(){ tourFinish(); },
    onfail: function(){ tourVirtual = true; tourV0 = Date.now(); jarvisLoopStart(); }   // voix introuvable : la visite se deroule quand meme, sous-titres seuls
  });
  jarvisLoopStart();
};
window.mcuTourSkip=function(){ tourFinish(); };
window.mcuTourDismiss=function(){ state.tourSeen = true; saveState(state); var r = document.getElementById('mcu-tour-root'); if (r) { r.innerHTML = ''; } };
window.mcuJarvisOrb=function(){ if (tourActive) return; window.mcuTourStart(); };
window.mcuVoiceToggle=function(on){ state.voiceOn = !!on; saveState(state); };

/* ---------------------------------------------------------------------------------------
   AUDIO DES SUCCES + SOUS-TITRES KARAOKE
   Timecodes au format "mm:ss". Pour corriger un timecode, modifie juste la ligne concernee.
   L(debut, fin, texte, qui?)  ->  "qui" est optionnel (etiquette du locuteur au-dessus de la ligne).
   Cle = id du succes dans ACHIEVEMENTS (50-down.mp3 -> 'mcu-veteran', mcu-completionist.mp3 -> 'completionist').
   --------------------------------------------------------------------------------------- */
function achParse(t){ var p = String(t).split(':'); return (parseInt(p[0],10)||0) * 60 + (parseInt(p[1],10)||0); }
function L(a, b, text, who, fx){ return { start: achParse(a), end: achParse(b), text: text, who: who || '', fx: fx || '' }; }

