/* ---- Lecteur ---- */
var achPlay = { id: null, raf: null, idx: -2, fx: '', words: [], starts: [], total: 1 };
var achQueue = [];   // succès débloqués en meme temps : annonces jouees les unes apres les autres

// Avatar rond affiche pendant la lecture (orbe en bas a droite + icone de la carte dans Mon Parcours).
// Pas d'entree = l'icone JARVIS (orbe cyan). Une URL (ou une fonction qui renvoie une URL) = image ronde.
var ACH_AVATAR = {
  // Liste d'URL essayees dans l'ordre : la 1re qui charge remplace l'orbe JARVIS pendant la lecture.
  'xmen-marathon': [
    "https://github.com/maerongrieshaber-a11y/mcu-images-/raw/main/deadpool.png",
    SFX_BASE + "deadpool.png",
    "https://github.com/maerongrieshaber-a11y/mcu-images-/raw/main/png%20deadpool.png",   // si le fichier s'appelle "png deadpool.png"
    SFX_BASE + "png%20deadpool.png",
    SFX_BASE + "deadpool.png.png",
    SFX_BASE + "Deadpool.png"
  ]
};
function achAvatarUrls(id){ var m = ACH_AVATAR[id]; if (!m) return []; return (typeof m === 'string') ? [m] : m.slice(); }

// Orbe : pose / retire l'avatar rond dans le disque central.
function achOrbSet(on, id){
  var o = document.getElementById('mcu-orb'); if (!o) return;
  var old = o.querySelector('.mcu-orb-avatar'); if (old && old.parentNode) { old.parentNode.removeChild(old); }
  o.classList.remove('has-avatar');
  var urls = on ? achAvatarUrls(id) : [], core = o.querySelector('.mcu-orb-core');
  if (!urls.length || !core) return;
  var img = new Image(), i = 0; img.className = 'mcu-orb-avatar'; img.alt = '';
  img.onload = function(){ if (img.parentNode !== core && achPlay.id === id) { core.appendChild(img); o.classList.add('has-avatar'); } };
  img.onerror = function(){ i++; if (i < urls.length) { img.src = urls[i]; } };   // URL suivante, sinon on garde l'orbe JARVIS
  img.src = urls[0];
}
// Effet piratage : classe .is-ultron sur l'orbe, les sous-titres et l'icone de la carte (selon le champ fx de la ligne en cours).
function achApplyFx(){
  var on = achPlay.fx === 'ultron' && !!achPlay.id;
  var o = document.getElementById('mcu-orb'), s = document.getElementById('mcu-sub');
  [o, s].forEach(function(e){ if (e) { e.classList.toggle('is-ultron', on); } });
}

function achSubBox(){
  var el = document.getElementById('mcu-sub');
  if (!el) { el = document.createElement('div'); el.id = 'mcu-sub'; el.className = 'mcu-sub'; document.getElementById('mcu-app').appendChild(el); }
  return el;
}
function achShowLine(line){
  var words = line.text.split(/\s+/), pos = 0, starts = [];
  words.forEach(function(w){ starts.push(pos); pos += w.length + 1; });
  achPlay.starts = starts; achPlay.total = pos || 1;
  achSubBox().innerHTML = (line.who ? '<span class="who">'+esc(line.who)+'</span>' : '')
    + words.map(function(w){ return '<span class="w">'+esc(w)+'</span>'; }).join(' ');
  achPlay.words = achSubBox().querySelectorAll('.w');
}
function achKaraoke(line, t){
  var f = Math.max(0, Math.min(1, (t - line.start) / Math.max(0.1, line.end - line.start)));
  var lim = f * achPlay.total;
  for (var i = 0; i < achPlay.words.length; i++) {
    if (achPlay.starts[i] <= lim) { achPlay.words[i].classList.add('on'); } else { achPlay.words[i].classList.remove('on'); }
  }
}
function achTick(id){
  if (achPlay.id !== id) return;
  var a = jarvis.audio, d = ACH_AUDIO[id];
  if (a) {
    var t = a.currentTime, idx = -1;
    for (var i = 0; i < d.lines.length; i++) { if (t >= d.lines[i].start - 0.05 && t < d.lines[i].end) { idx = i; break; } }
    if (idx !== achPlay.idx) {
      achPlay.idx = idx;
      var box = achSubBox();
      if (idx < 0) { box.classList.remove('on'); }   // entre deux lignes : on garde l'effet en cours
      else { achShowLine(d.lines[idx]); box.classList.add('on'); achPlay.fx = d.lines[idx].fx || ''; }
    }
    if (idx >= 0) { achKaraoke(d.lines[idx], t); }
    achApplyFx();
  }
  achPlay.raf = requestAnimationFrame(function(){ achTick(id); });
}
function achRefreshUI(){ if (view === 'journey') { withPreservedScroll(function(){ renderApp(); }); } }
function achStop(keepDuck){
  if (achPlay.raf) { cancelAnimationFrame(achPlay.raf); achPlay.raf = null; }
  var had = achPlay.id;
  achPlay.id = null; achPlay.idx = -2; achPlay.fx = '';
  jarvisStop();                                         // coupe l'audio precedent (jamais deux voix en meme temps)
  var box = document.getElementById('mcu-sub'); if (box) { box.classList.remove('on', 'is-ultron'); }
  var o = document.getElementById('mcu-orb'); if (o && o.classList) { o.classList.remove('speaking', 'is-ultron'); }
  achOrbSet(false);                                     // l'orbe retrouve son look JARVIS bleu / cyan
  if (!keepDuck && !tourActive) { musicSetDuck(false); }   // la musique d'ambiance reprend
  if (had) { achRefreshUI(); }
}
function achStart(id){
  var d = ACH_AUDIO[id]; if (!d || tourActive) return;
  achStop(true);
  achPlay.id = id;
  musicSetDuck(true);                                   // musique en pause pendant la voix
  jarvisPlay(d.url, {
    onstart: function(){ if (achPlay.id === id) { achOrbSet(true, id); achTick(id); achRefreshUI(); } },
    onend: function(){
      if (achPlay.id !== id) return;
      achStop(achQueue.length > 0);
      if (achQueue.length) { achStart(achQueue.shift()); }
    },
    onfail: function(){                                 // fichier introuvable OU lecture bloquee par le navigateur
      if (achPlay.id !== id) return;
      achStop();
      showToast('\uD83D\uDD07', 'AUDIO', 'Lecture impossible', 'Clique sur \u00AB R\u00E9\u00E9couter \u00BB depuis Mon Parcours pour r\u00E9essayer.');
    }
  });
  achRefreshUI();
}
// Annonce automatique au deblocage (appelee par showAchievementToast).
function jarvisAnnounce(a){
  if (tourActive || state.voiceOn === false || !ACH_AUDIO[a.id]) return;
  if (achPlay.id) { achQueue.push(a.id); } else { achStart(a.id); }
}
// Bouton "Reecouter" / "Arreter" (relance manuelle, ignore l'option voix coupee)
window.mcuReplayAch = function(id){
  achQueue = [];
  if (achPlay.id === id) { achStop(); return; }
  achStart(id);
};
function renderTourPrompt(){
  var root = document.getElementById('mcu-tour-root'); if (!root) return;
  root.innerHTML = '<div class="mcu-tour-prompt"><div class="mcu-tour-prompt-card">'
    + '<div class="mcu-orb-demo" style="--lv:0.3">'+jarvisOrbInner()+'</div>'
    + '<div class="disp" style="font-size:34px;color:#7fe6ff;letter-spacing:0.08em">JARVIS</div>'
    + '<p style="color:#B7D4E0;font-size:14px;line-height:1.6;margin:12px 0 22px">Bienvenue. Souhaitez-vous une pr\u00E9sentation guid\u00E9e du site ?<br><span style="color:#7C93A0;font-size:12.5px">Environ 1 minute, avec le son activ\u00E9.</span></p>'
    + '<div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap"><button class="btn-cta" onclick="mcuTourStart()">\u25B6 Lancer la pr\u00E9sentation</button><button class="btn" onclick="mcuTourDismiss()">Passer</button></div>'
    + '</div></div>';
}
// Precharge les sons des cartes en arriere-plan : ils sont prets au premier paquet, sans latence.
function preloadCardSounds(){
  try {
    Object.keys(RARITY_SFX).forEach(function(r){
      if (!raritySfxAudio[r]) { var a = new Audio(RARITY_SFX[r].data); a.preload = 'auto'; raritySfxAudio[r] = a; }
    });
    if (!lobbyAudio) { lobbyAudio = new Audio(LOBBY_SFX_DATA); lobbyAudio.loop = true; lobbyAudio.volume = 0.7; lobbyAudio.preload = 'auto'; }
    if (!mythicSfxAudio) {
      mythicSfxAudio = new Audio(MYTHIC_SFX_DATA); mythicSfxAudio.preload = 'auto';
      mythicSfxAudio.addEventListener('error', function(){ mythicSfxBroken = true; synthReveal('Mythique'); });
    }
  } catch(e){}
}
function jarvisInit(){
  renderJarvisOrb();
  if (!state.tourSeen && !sharedProfile) { renderTourPrompt(); }
}


/* ---------------------------------------------------------------------------------------
   COVER DU PAQUET DE CARTES : image "booster" deposee sur GitHub (a la racine du depot).
   Plusieurs extensions sont essayees ; si aucune n'existe, l'ancien paquet (degrade + logo) reste.
   Pour changer le nom ou le dossier : modifie uniquement BOOSTER_FILES.
   --------------------------------------------------------------------------------------- */
var BOOSTER_FILES = ['booster.webp', 'booster.jpeg', 'booster.jpg', 'booster.png', 'booster.webp', 'cartes/booster.jpeg', 'cartes/booster.jpg', 'cartes/booster.png', 'cartes/booster.webp', 'sons/booster.jpeg'];
var packCover = { started: false, ok: false, url: '', ratio: 0 };
function packCoverLoad(){
  if (packCover.started) return; packCover.started = true;
  var i = 0;
  (function next(){
    if (i >= BOOSTER_FILES.length) return;
    var url = SFX_BASE + BOOSTER_FILES[i++], im = new Image();
    im.onload = function(){
      packCover.ok = true; packCover.url = url;
      packCover.ratio = (im.naturalWidth && im.naturalHeight) ? (im.naturalWidth / im.naturalHeight) : (2/3);
      if (packState && packState.idx < 0 && !packState.opening) { renderPack(); }
    };
    im.onerror = next;
    im.src = url;
  })();
}
function packCoverAttrs(){
  packCoverLoad();
  if (!packCover.ok) return '';
  return ' has-cover" style="background-image:url(\'' + packCover.url + '\');aspect-ratio:' + packCover.ratio.toFixed(4);
}

/* --- Ouverture de paquet --- */
var packState = null;   // { ids:[...], idx:-1 (paquet ferme) ou index de la carte revelee, opening:bool }
function showPack(ids){
  var list = ids.map(cardById).filter(Boolean).sort(function(a,b){ return (RARITY_RANK[a.rarity]||0) - (RARITY_RANK[b.rarity]||0); });
  if (!list.length) return;
  packState = { ids: list.map(function(c){ return c.id; }), idx: -1, opening: false };   // les plus rares en dernier : suspense
  renderPack();
  musicSetDuck(true); startLobby();   // la musique d'ambiance se met en pause, la musique d'attente du paquet tourne
}
function renderPack(){
  var root = document.getElementById('mcu-pack-root'); if (!root) return;
  if (!packState) { root.innerHTML = ''; return; }
  var n = packState.ids.length;
  var h = '<div class="mcu-pack-overlay"><div class="mcu-pack-tools">'
    + '<button type="button" onclick="mcuToggleSound()" title="Son">'+(soundOn() ? '\uD83D\uDD0A' : '\uD83D\uDD07')+'</button>'
    + '<button type="button" onclick="mcuPackClose()" title="Fermer">\u2715</button></div>';
  if (packState.idx < 0) {
    h += '<div class="mcu-pack'+(packState.opening ? ' mcu-pack-opening' : '')+packCoverAttrs()+'"><div class="mcu-pack-shine"></div>'
      + '<div class="disp mcu-pack-logo"><span class="gold">MCU</span><br>TIMELINE</div><div class="mono mcu-pack-sub">PAQUET DE CARTES</div></div>'
      + '<div class="disp" style="font-size:28px;margin-top:26px;text-align:center">Nouveau paquet !</div>'
      + '<div style="color:#B7B2AA;font-size:13px;margin:4px 0 18px;text-align:center">'+n+' carte'+(n>1?'s':'')+' d\u00E9bloqu\u00E9e'+(n>1?'s':'')+'</div>'
      + '<button class="btn-cta" '+(packState.opening ? 'disabled' : '')+' onclick="mcuPackOpen()">Ouvrir le paquet</button>';
  } else {
    var c = cardById(packState.ids[packState.idx]), rs = RARITY_STYLE[c.rarity] || RARITY_STYLE["Commune"], sparks = '';
    if (packState.waiting) {
      var wt = (packState.waitDur || 2.5).toFixed(2), wsp = '';
      for (var wi=0; wi<12; wi++) { wsp += '<span class="mcu-wspark" style="left:'+Math.round(-10 + Math.random()*120)+'%;top:'+Math.round(Math.random()*110)+'%;animation-delay:'+(Math.random()*1.4).toFixed(2)+'s"></span>'; }
      h += '<div class="mcu-wait-glow" style="--rcs:'+rs.color+'66;--wt:'+wt+'s"></div>'
        + '<div class="mcu-flipwrap mcu-wander" style="--rc:'+rs.color+';--rcs:'+rs.color+'88;--wt:'+wt+'s">'
        + '<div class="mcu-rays"></div><div class="mcu-ring"></div><div class="mcu-ring" style="animation-delay:.6s"></div>'
        + '<div class="mcu-tiltbox"><div class="mcu-flipcard mcu-waiting"><div class="mcu-flipfront"></div>'
        + '<div class="mcu-flipback"><div class="disp mcu-pack-logo"><span class="gold">MCU</span><br>TIMELINE</div></div></div></div>'+wsp+'</div>'
        + '<div class="mono" style="margin-top:26px;color:'+rs.color+';letter-spacing:0.14em;font-size:12px">\u2026</div>'
        + '<button class="btn" style="margin-top:14px" onclick="mcuPackSkip()">Passer</button></div>';
      root.innerHTML = h; return;
    }
    if ((RARITY_RANK[c.rarity] || 0) >= 3) {
      for (var i=0; i<14; i++) { sparks += '<span class="mcu-spark" style="left:'+Math.round(Math.random()*100)+'%;top:'+Math.round(Math.random()*100)+'%;animation-delay:'+((packState.timed ? 1.0 : 1.4)+Math.random()*1.2).toFixed(2)+'s;background:'+rs.color+';color:'+rs.color+'"></span>'; }
    }
    var flash = (RARITY_RANK[c.rarity] || 0) >= 3 ? '<div class="mcu-flash" style="'+(packState.timed ? 'animation-delay:.75s;' : '')+'background:radial-gradient(circle at 50% 40%, '+rs.color+'cc, transparent 65%)"></div>' : '';
    h += flash + '<div class="mcu-flipwrap" onpointermove="mcuTilt(event,this)" onpointerleave="mcuTiltReset(this)"><div class="mcu-burst" style="'+(packState.timed ? 'animation-delay:.95s;' : '')+'border-color:'+rs.color+'"></div>'
      + '<div class="mcu-tiltbox" data-rank="'+(RARITY_RANK[c.rarity]||0)+'"><div class="mcu-flipcard"'+(packState.timed ? ' style="animation-delay:0s;animation-duration:1.35s"' : '')+'><div class="mcu-flipfront">'+renderCardFace(c, '100%')+'</div>'
      + '<div class="mcu-flipback"><div class="disp mcu-pack-logo"><span class="gold">MCU</span><br>TIMELINE</div></div></div></div>'+sparks+'</div>'
      + '<div style="margin-top:10px;font-size:11px;color:#6E7480">Fais glisser la carte pour l\'incliner</div>'
      + '<div class="mono" style="margin-top:22px;color:'+rs.color+';letter-spacing:0.14em;font-size:12px">'+esc(c.rarity.toUpperCase())+'</div>'
      + '<div class="disp" style="font-size:26px;margin:2px 0 16px;text-align:center">'+esc(c.name)+'</div>'
      + '<div style="display:flex;gap:10px;flex-wrap:wrap;justify-content:center">'
      + (packState.idx < n-1
          ? '<button class="btn-cta" onclick="mcuPackNext()">Carte suivante ('+(packState.idx+1)+'/'+n+')</button>'
          : '<button class="btn-cta" onclick="mcuPackClose()">Terminer</button><button class="btn" onclick="mcuPackClose();mcuGoto(\'characters\')">Voir ma collection</button>')
      + '</div>';
  }
  h += '</div>';
  root.innerHTML = h;
}
// Les cartes Mythiques utilisent le son des Pierres d'Infinité dès le début de leur ouverture.
// Pour les autres raretés, on garde le système sonore classique.
function packRevealSound(){
  var s = packState; if (!s || s.idx < 0) return;
  var idx = s.idx, c = cardById(s.ids[idx]);
  setTimeout(function(){
    if (packState && packState.idx === idx && c && c.rarity !== 'Mythique') {
      sfxReveal(c.rarity);
    }
  }, 1150);
}

/* --- Fiche detaillee d'une carte : visuel de carte (portrait) a gauche, infos a droite --- */
var NORMAL_FORMAT_CARDS = ['card-lieu-tour-avengers','card-lieu-sanctum','card-lieu-knowhere','card-lieu-hells-kitchen','card-lieu-quantique','card-lieu-ego','card-lieu-daily-bugle'];
function imgNatural(url, fb, alt){
  return '<img src="'+esc(url)+'" data-fb="'+esc(fb||'')+'" alt="'+esc(alt||'')+'" style="display:block;width:100%;height:auto" onerror="var f=(this.getAttribute(\'data-fb\')||\'\').split(\'|\'),n=f.shift();this.setAttribute(\'data-fb\',f.join(\'|\'));if(n){this.src=n;}else{this.onerror=null;this.style.display=\'none\';}">';
}
function renderWideCard(c){
  var rs = RARITY_STYLE[c.rarity] || RARITY_STYLE["Commune"], img = CARD_IMAGES[c.id], pal = paletteFor(c.id);
  var fb = (typeof CARD_IMAGES_FALLBACK!=='undefined' ? CARD_IMAGES_FALLBACK[c.id] : '') || '';
  return '<div class="mcu-wide'+rarityFxClass(c.rarity)+'" style="--glow:'+rs.glow+';position:relative;border-radius:14px;overflow:hidden;border:2px solid '+rs.color+';box-shadow:0 0 26px 4px '+rs.glow+';min-height:170px;background:linear-gradient(160deg,'+pal[0]+'99,'+pal[1]+')">'
    + (img ? imgNatural(img, fb, 'Carte '+c.name) : '')
    + catBadge(c)
    + '<div class="mono" style="position:absolute;top:8px;right:8px;background:'+rs.color+';color:#08070C;font-size:9px;font-weight:700;padding:3px 9px;border-radius:999px;letter-spacing:0.04em">'+esc(c.rarity.toUpperCase())+'</div>'
    + '<div style="position:absolute;left:0;right:0;bottom:0;padding:14px 16px;background:linear-gradient(to top, rgba(6,5,9,0.92) 25%, rgba(6,5,9,0.45) 70%, transparent)">'
    + '<div class="disp" style="font-size:24px;line-height:1.05;color:#EDEAE3">'+esc(c.name)+'</div>'
    + '<div style="font-size:12px;color:#C9C4BC;margin-top:3px;font-style:italic">'+esc(c.tag)+'</div></div></div>';
}
function renderCardDetailModal(){
  var c = cardById(currentCardId); if (!c) return '';
  var rs = RARITY_STYLE[c.rarity] || RARITY_STYLE["Commune"];
  var ch = cardCharacter(c), it = c.unlock ? itemById(c.unlock) : null, color = rs.color;
  var html = '<div class="modal-overlay" onclick="if(event.target===this)mcuCloseCardModal()"><div class="modal-box">';
  html += '<div style="padding:16px 20px 0;display:flex;justify-content:space-between;align-items:center">'
    + '<button onclick="mcuCloseCardModal()" style="background:rgba(10,9,13,0.6);border-radius:999px;padding:6px 14px;color:#EDEAE3;font-size:13px">\u2190 Retour</button>'
    + '<span class="mono" style="font-size:11px;color:'+color+';letter-spacing:0.1em">'+esc(c.rarity.toUpperCase())+'</span></div>';
  var wide = (c.cat === 'Endroit' && NORMAL_FORMAT_CARDS.indexOf(c.id) === -1);   // les artefacts et ces lieux gardent le format carte
  html += '<div style="padding:18px 26px 28px;'+(wide ? '' : 'display:flex;flex-wrap:wrap;gap:28px;justify-content:center;align-items:flex-start')+'">';
  if (wide) {
    html += renderWideCard(c) + '<button class="btn" style="margin:10px 0 16px" onclick="mcuReplayPack(\''+c.id+'\')">\u25B6 Revoir l\'ouverture</button>';
  } else {
    html += '<div style="flex:0 0 auto;width:min(270px,78vw)"><div class="mcu-flipwrap" style="width:100%;cursor:grab" onpointermove="mcuTilt(event,this)" onpointerleave="mcuTiltReset(this)"><div class="mcu-tiltbox" data-rank="'+(RARITY_RANK[c.rarity]||0)+'">'+renderCardFace(c, '100%')+'</div></div>'
      + '<button class="btn" style="width:100%;margin-top:12px" onclick="mcuReplayPack(\''+c.id+'\')">\u25B6 Revoir l\'ouverture</button></div>';
  }
  html += '<div style="flex:1 1 260px;min-width:240px">'
    + '<h1 class="disp" style="font-size:34px;line-height:1;color:'+color+';margin:2px 0 6px">'+esc(c.name)+'</h1>'
    + '<div style="font-size:13.5px;color:#C9C4BC;font-style:italic;margin-bottom:16px">'+esc(c.tag)+'</div>';
  if (it) {
    html += '<div class="card" style="border-color:'+color+'55;margin-bottom:16px;padding:12px 14px"><div style="font-size:11px;color:#9AA0AA;margin-bottom:4px">D\u00E9bloqu\u00E9e apr\u00E8s le quiz</div>'
      + '<button class="disp" style="color:#C9A24B;font-size:18px;text-align:left" onclick="mcuOpen(\''+it.id+'\')">'+esc(it.title)+' \u2192</button></div>';
  }
  if (ch) {
    if (ch.comic) { html += comicFirstHtml(ch.comic, color); }
    html += '<h2 class="disp" style="color:'+color+';font-size:20px;margin-bottom:6px">Histoire</h2><p style="color:#D8D4CB;line-height:1.6;margin-bottom:18px;font-size:14px">'+esc(ch.backstory)+'</p>';
    if (ch.keyActs && ch.keyActs.length) {
      html += '<h2 class="disp" style="color:'+color+';font-size:20px;margin-bottom:8px">Faits marquants</h2><ul style="margin:0 0 18px 18px;padding:0;color:#D8D4CB;line-height:1.7;font-size:14px">'
        + ch.keyActs.map(function(a){ return '<li>'+esc(a)+'</li>'; }).join('') + '</ul>';
    }
    if (ch.funFact) {
      html += '<div class="card" style="border-color:'+color+'88;margin-bottom:18px"><div style="font-size:11px;color:#9AA0AA;margin-bottom:4px">Anecdote</div><span style="font-size:14px">'+esc(ch.funFact)+'</span></div>';
    }
    if (ch.films && ch.films.length) {
      html += '<h2 class="disp" style="color:'+color+';font-size:20px;margin-bottom:8px">Apparitions</h2><div style="display:flex;flex-wrap:wrap;gap:8px">'
        + ch.films.map(function(fid){ var f = itemById(fid); return f ? '<button class="badge" style="cursor:pointer" onclick="mcuOpen(\''+f.id+'\')">'+esc(f.title)+'</button>' : ''; }).join('') + '</div>';
    }
  } else {
    if (FIRST_COMIC_CARDS[c.id]) { html += comicFirstHtml(FIRST_COMIC_CARDS[c.id], color); }
    if (c.desc) { html += '<h2 class="disp" style="color:'+color+';font-size:20px;margin-bottom:6px">'+(c.cat==='Artefact'?'L\'artefact':'Le lieu')+'</h2><p style="color:#D8D4CB;line-height:1.6;font-size:14px">'+esc(c.desc)+'</p>'; }
    else { html += '<p style="color:#6E7480;font-size:13px">Cette version de carte n\'a pas de fiche d\u00E9taill\u00E9e : seul le personnage principal en poss\u00E8de une.</p>'; }
  }
  html += '</div></div></div></div>';
  return html;
}

function unlockRequirementLabel(c){
  var it = c.unlock ? itemById(c.unlock) : null;
  return it ? it.title : "un contenu a venir";
}

function renderCharactersView(){
  var query = filters.cardQuery || '';
  var rarityFilter = filters.cardRarity || 'Toutes';
  var list = CARDS.filter(function(c){
    if (rarityFilter !== 'Toutes' && c.rarity !== rarityFilter) return false;
    if ((filters.cardCat||'Toutes') !== 'Toutes' && c.cat !== filters.cardCat) return false;
    if (query && c.name.toLowerCase().indexOf(query.toLowerCase()) === -1) return false;
    return true;
  });
  var unlockedCount = CARDS.filter(function(c){ return cardIsUnlocked(c); }).length;

  var html='<div class="wrap"><div class="hero">'
    + '<h1 class="disp" style="font-size:34px">CARTES A COLLECTIONNER</h1>'
    + '<p style="color:#9AA0AA">'+unlockedCount+' / '+CARDS.length+' cartes débloquées. Réussis le quiz d\'un film ou d\'une serie pour en reveler de nouvelles.</p>'
    + '<button class="btn" style="margin-top:8px" onclick="mcuToggleSound()">'+(soundOn() ? '\uD83D\uDD0A Son des paquets : activ\u00E9' : '\uD83D\uDD07 Son des paquets : coup\u00E9')+'</button>'
    + '</div>';

  var sortMode = filters.cardSort || 'Ordre actuel';
  var RK = { Mythique:0, Legendaire:1, Epique:2, Rare:3, Commune:4 };
  html += '<div class="filters">'
    + renderSearchBox(query, 'card-search', 'cardQuery', 'Rechercher une carte...', false)
    + '<select onchange="mcuSetFilter(\'cardRarity\', this.value)">'
    + ['Toutes','Commune','Rare','Epique','Legendaire','Mythique'].map(function(r){return '<option '+(rarityFilter===r?'selected':'')+'>'+r+'</option>';}).join('')
    + '</select>'
    + '<select title="Catégorie" onchange="mcuSetFilter(\'cardCat\', this.value)">'
    + ['Toutes','Héros','Tenue','Endroit','Artefact','Collector'].map(function(r){return '<option value="'+r+'" '+((filters.cardCat||'Toutes')===r?'selected':'')+'>'+(r==='Toutes'?'Toutes catégories':r)+'</option>';}).join('')
    + '</select>'
    + '<select title="Trier" onchange="mcuSetFilter(\'cardSort\', this.value)">'
    + [['Ordre actuel','Tri : ordre actuel'],['Rarete','Tri : rareté'],['Contenu','Tri : contenu (timeline)']].map(function(o){ return '<option value="'+o[0]+'" '+(sortMode===o[0]?'selected':'')+'>'+o[1]+'</option>'; }).join('')
    + '</select></div>';

  var groups = [];
  if (sortMode === 'Rarete') {
    ['Mythique','Legendaire','Epique','Rare','Commune'].forEach(function(r){
      var g = list.filter(function(c){ return c.rarity === r; });
      if (g.length) groups.push({ title: r + ' (' + g.length + ')', color: (RARITY_STYLE[r] || {}).color, cards: g });
    });
  } else if (sortMode === 'Contenu') {
    var orderIds = ITEMS.slice().sort(function(a,b){ return a.order - b.order; }).map(function(i){ return i.id; })
      .concat(OTHER.map(function(o){ return o.id; }), UPCOMING_ITEMS.map(function(u){ return u.id; }));
    orderIds.forEach(function(id){
      var g = list.filter(function(c){ return c.unlock === id; }).sort(function(a,b){ return (RK[a.rarity]||0) - (RK[b.rarity]||0); });
      if (g.length) groups.push({ title: itemById(id).title + ' (' + g.length + ')', cards: g });
    });
    var rest = list.filter(function(c){ return orderIds.indexOf(c.unlock) === -1; });
    if (rest.length) groups.push({ title: (rest.every(function(c){ return c.cat === 'Collector'; }) ? 'Cartes collector' : 'A assigner') + ' (' + rest.length + ')', cards: rest });
  } else {
    groups.push({ title: '', cards: list });
  }
  groups.forEach(function(g){
    if (g.title) { html += '<div class="disp" style="font-size:20px;color:'+(g.color || '#C9A24B')+';margin:24px 0 10px">'+esc(g.title)+'</div>'; }
    html += '<div class="grid mcu-cards-grid" style="grid-template-columns:repeat(auto-fill, minmax(150px, 1fr))">';
    g.cards.forEach(function(c){ html += renderCard(c); });
    html += '</div>';
  });
  html += '</div>';
  return html;
}

function renderHorsMCUView(){
  var q=(filters.hmQuery||'').toLowerCase(), uni=filters.hmUni||'Tous';
  var all={}; OTHER.forEach(function(o){ all[o.universe]=1; });
  var groups = {};
  OTHER.filter(function(o){ return statusOk(o.id) && (uni==='Tous'||o.universe===uni) && (!q||o.title.toLowerCase().indexOf(q)!==-1); }).forEach(function(o){ (groups[o.universe] = groups[o.universe] || []).push(o); });
  var html = '<div class="wrap"><div class="hero"><h1 class="disp" style="font-size:34px">HORS MCU</h1>'
    + '<p style="color:#9AA0AA">Les autres univers Marvel à l\'écran (Sam Raimi, Sony, X-Men, autres studios), ainsi que l\'animation MCU et les séries annexes.</p></div>';
  html += '<div class="filters">' + renderSearchBox(filters.hmQuery||'','hm-search','hmQuery','Rechercher un titre...',false)
    + '<div class="mcu-frow"><select title="Univers" onchange="mcuSetFilter(\'hmUni\', this.value)"><option value="Tous">Tous les univers</option>'
    + Object.keys(all).map(function(u){return '<option value="'+esc(u)+'" '+(uni===u?'selected':'')+'>'+esc(u)+'</option>';}).join('')+'</select>'
    + statusSelectHtml() + selectBtnHtml() + '</div></div>';
  if(!Object.keys(groups).length){ html += '<p style="color:#6E7480;text-align:center;margin:30px 0">Aucun résultat.</p>'; }
  Object.keys(groups).forEach(function(universe){
    html += '<div style="margin-bottom:32px"><div class="disp" style="font-size:22px;color:#5B6FE8;margin-bottom:12px">'+esc(universe)+'</div><div class="grid">';
    groups[universe].sort(function(a,b){return (a.year-b.year)||((a.month||0)-(b.month||0));}).forEach(function(o){
      html += '<div class="card mcu-card'+(bulkSel[o.id]?' sel':'')+'" style="cursor:pointer;padding:0;overflow:hidden" onclick="mcuRowClick(\''+o.id+'\')">'
        + posterHtml(o) + '<div style="padding:12px"><div class="t-meta">'+o.year+' \u00B7 '+o.type+'</div>'
        + '<div class="disp" style="font-size:18px">'+esc(o.title)+'</div>'
        + (state.watched[o.id] ? '<span class="v-watched-tag" style="margin-top:6px">\u2713 VU</span>' : '') + '</div></div>';
    });
    html += '</div></div>';
  });
  return html + '</div>';
}

function renderMultiverseView(){
  var html='<div class="wrap"><div class="hero" style="text-align:center;display:flex;flex-direction:column;align-items:center">'
    + '<div class="mono" style="font-size:11px;letter-spacing:0.25em;color:#5B6FE8">'+MULTIVERSE.length+' REALITES CATALOGUEES</div>'
    + '<h1 class="disp">LE <span style="color:#5B6FE8">MULTIVERS</span></h1>'
    + '<p style="color:#B7B2AA;font-size:13.5px;max-width:640px;margin-top:4px">Depuis la rupture du Sacred Timeline, d\'innombrables realites coexistent d\u00E9sormais, chacune avec sa propre histoire, ses propres regles... et ses propres dangers.</p>'
    + '</div>';

  html += '<div class="card" style="margin:6px 0 16px;border-color:#2E9E83;background:linear-gradient(120deg,rgba(46,158,131,0.14),rgba(232,196,104,0.06))"><div class="disp" style="font-size:20px;color:#E8C468;margin-bottom:6px">De Kang à Doom : une nouvelle menace</div><div style="font-size:13px;color:#D8D4CB;line-height:1.6">Avengers: The Kang Dynasty a été abandonné après le renvoi de Jonathan Majors par Marvel en 2023. Au Comic-Con 2024, Marvel a annoncé Avengers: Doomsday (18 décembre 2026), avec Robert Downey Jr. dans le rôle de Victor von Doom, puis Avengers: Secret Wars (17 décembre 2027). Les deux films concluent la Multiverse Saga : la menace principale à l\'écran est désormais Victor von Doom, et non plus Kang. Les liens exacts avec les autres réalités restent à confirmer par les films.</div></div>';
  // Frise de lore : comment le multivers s'est ouvert, en 4 etapes.
  html += '<div class="mcu-lore-steps">' + MULTIVERSE_LORE.map(function(s){
    return '<div class="mcu-lore-step"><div class="mcu-lore-num">'+String(s.num).padStart(2,'0')+'</div>'
      + '<div class="mcu-lore-title">'+esc(s.title)+'</div>'
      + '<div class="mcu-lore-desc">'+esc(s.desc)+'</div></div>';
  }).join('') + '</div>';

  html += '<div class="card" style="margin:6px 0 14px;font-size:12.5px;color:#B7B2AA;line-height:1.6"><strong style="color:#EDEAE3">Échelle de danger</strong> (note purement indicative) : 1 = réalité calme · 2 = tensions locales · 3 = menaces sérieuses · 4 = menace majeure pour plusieurs mondes · 5 = péril pour le multivers entier.</div>';
  // Grille des realites. Fond bien colore et opaque (pas de "transparent" qui laisse
  // transparaitre l'image de fond du site derriere les cartes).
  html += '<div class="mcu-reality-grid">' + MULTIVERSE.map(function(u){
    var linked = (u.linked||[]).map(itemById).filter(Boolean);
    var dots = '';
    for (var i=1;i<=5;i++){ dots += '<span style="'+(i<=u.danger?('background:'+u.color):'')+'"></span>'; }
    return '<div class="mcu-reality-card2" style="border-color:'+u.color+'88;background:linear-gradient(160deg,'+u.color+'40,'+u.color+'12 45%,#131117 85%)">'
      + '<div class="mcu-reality-emblem" style="background:'+u.color+'33;color:'+u.color+'">'+u.icon+'</div>'
      + '<div>'
      + '<span class="mcu-reality-tag" style="color:'+u.color+'">'+esc(u.tag)+'</span>'
      + '<div class="disp" style="font-size:22px;color:'+u.color+';margin-top:6px">'+esc(u.name)+'</div>'
      + '</div>'
      + '<p style="font-size:13px;color:#D8D4CB;line-height:1.5;flex:1">'+esc(u.desc)+'</p>'
      + '<div style="display:flex;align-items:center;justify-content:space-between;font-size:10.5px;color:#8A8690">'
      + '<span>NIVEAU DE DANGER</span><span class="mcu-danger-dots">'+dots+'</span></div>'
      + (linked.length ? ('<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px">' + linked.map(function(it){
          return '<button class="badge" style="cursor:pointer;border-color:'+u.color+';font-size:11px" onclick="mcuOpen(\''+it.id+'\')">'+esc(it.title)+'</button>';
        }).join('') + '</div>') : '')
      + '</div>';
  }).join('') + '</div>';

  html += '</div>';
  return html;
}

