function renderSharedProfileView(){
  var p = sharedProfile;
  var topItems = (p.top || []).map(itemById).filter(Boolean);
  var favChar = p.fc ? charById(p.fc) : null;

  var html = '<div class="wrap">';
  html += '<div class="mcu-profile-hero">'
    + '<div class="mono" style="font-size:11px;letter-spacing:0.2em;color:#5B6FE8;margin-bottom:6px">PROFIL PARTAGE</div>'
    + '<div class="mcu-avatar-ring">'
    + '<div class="mcu-avatar-inner">' + (p.a ? ('<img src="'+esc(p.a)+'" alt="'+esc('Photo de profil de '+(p.n||''))+'" style="width:100%;height:100%;object-fit:cover">') : '\uD83E\uDDB8') + '</div>'
    + '</div>'
    + '<h1 class="disp" style="font-size:32px;margin:8px 0 0">'+esc(p.n)+'</h1>'
    + (p.b ? '<p style="color:#B7B2AA;font-size:13.5px;max-width:420px;margin:6px 0 0">'+esc(p.b)+'</p>' : '')
    + '<div class="badge" style="border-color:#C9A24B;color:#E8C468;margin-top:10px">Lv.'+esc(p.lvl)+' \u2014 '+esc(p.lvlName)+' \u00B7 '+esc(p.xp)+' XP</div>'
    + '</div>';

  if (topItems.length) {
    var podiumSizes = [148, 128, 112, 98, 86];
    html += '<div class="disp" style="font-size:20px;color:#C9A24B;margin-bottom:4px;text-align:center">Top '+topItems.length+'</div>';
    html += '<div class="mcu-podium">' + topItems.map(function(it, idx){
      var w = podiumSizes[idx] || 80;
      return '<div class="mcu-podium-item" style="width:'+w+'px">'
        + '<div class="mcu-podium-poster-wrap" style="width:'+w+'px;cursor:pointer" onclick="mcuOpen(\''+it.id+'\')">'
        + '<div class="mcu-podium-rank">'+(idx+1)+'</div>'
        + imgWithFallback(resolvePosterUrl(it.id), '', 'Affiche : '+it.title)
        + '</div>'
        + '<div class="mcu-podium-title">'+esc(it.title)+'</div></div>';
    }).join('') + '</div>';
  }

  if (favChar) {
    var pal = paletteFor(favChar.id);
    var color = favChar.color || pal[0];
    html += '<div class="disp" style="font-size:20px;color:#C9A24B;margin:24px 0 4px;text-align:center">'+'Personnage pr\u00E9f\u00E9r\u00E9'+'</div>';
    html += '<div class="card" style="max-width:380px;margin:14px auto 0;display:flex;gap:16px;align-items:center;border-color:'+color+';cursor:pointer" onclick="mcuOpenChar(\''+favChar.id+'\')">'
      + '<div style="width:64px;height:64px;border-radius:50%;overflow:hidden;flex-shrink:0;position:relative;background:linear-gradient(135deg,'+color+',#08070C)">'+imgWithFallback(cardImageForChar(favChar.id), '', favChar.name)+'</div>'
      + '<div style="flex:1;text-align:left;min-width:0">'
      + '<div class="disp" style="font-size:18px;color:'+color+';white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(favChar.name)+'</div>'
      + '<div style="font-size:11px;color:#8A8690">'+esc(tierLabel(favChar.tier))+'</div></div>'
      + '</div>';
  }

  html += '<div style="margin:24px 0;color:#B7B2AA;text-align:center">\uD83C\uDFC6 '+esc(p.ach)+' / '+esc(p.achTotal)+' succès débloqués</div>';
  html += '<div style="text-align:center;margin-bottom:20px"><button class="btn-cta" onclick="mcuExitSharedProfile()">Voir mon propre profil</button></div>';
  html += '</div>';
  return html;
}

function renderProfileView(){
  if (sharedProfile) return renderSharedProfileView();
  var prog = computeProgress(state);
  var html = '<div class="wrap">';

  html += '<div class="mcu-profile-hero">';
  html += '<div class="mcu-avatar-ring">'
    + '<div class="mcu-avatar-inner">'
    + (state.profile.avatar ? '<img src="'+esc(state.profile.avatar)+'" alt="Ma photo de profil" style="width:100%;height:100%;object-fit:cover">' : '\uD83E\uDDB8')
    + '</div>'
    + '<button class="mcu-avatar-edit" onclick="document.getElementById(\'mcu-avatar-input\').click()" title="Changer la photo">\u270F\uFE0F</button>'
    + '<input type="file" id="mcu-avatar-input" accept="image/*" style="display:none" onchange="mcuUploadAvatar(this)">'
    + '</div>';
  html += '<input class="mcu-profile-name-input" data-focus-id="profile-name" value="'+esc(state.profile.name)+'" placeholder="Choisis un pseudo" oninput="mcuSetProfileName(this.value)">';
  html += '<textarea class="mcu-profile-bio-input" data-focus-id="profile-bio" rows="2" maxlength="140" placeholder="Ajoute une petite bio... (140 caract\u00E8res max)" oninput="mcuSetProfileBio(this.value)">'+esc(state.profile.bio)+'</textarea>';
  html += '<div class="badge" style="border-color:#C9A24B;color:#E8C468;margin-top:4px">Lv.'+prog.level.level+' \u2014 '+esc(prog.level.name)+'</div>';
  html += '<div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-top:8px">'
    + '<button class="btn-cta" onclick="mcuShareProfile()">'+'\uD83D\uDD17 Partager le lien'+'</button>'
    + '<button class="btn-cta" onclick="mcuDownloadShareCard()">'+"\uD83D\uDCF8 T\u00E9l\u00E9charger l'image (Insta/Snap)"+'</button>'
    + '</div>';
  html += '</div>';

  html += '<div class="card" style="margin-bottom:24px">'
    + '<div style="display:flex;justify-content:space-between;font-size:12px;color:#9AA0AA;margin-bottom:6px">'
    + '<span>'+prog.xp+' XP</span>'
    + '<span>'+(prog.level.next ? ('Encore '+prog.xpToNext+' XP avant le niveau '+prog.level.next.level) : 'Niveau maximum atteint !')+'</span></div>'
    + '<div style="height:8px;border-radius:999px;background:#1c1a21;overflow:hidden">'
    + '<div style="height:100%;background:linear-gradient(90deg,#C9A24B,#5B6FE8);width:'+(prog.level.next ? Math.min(100, Math.round((prog.xp-prog.level.minXp)/(prog.level.next.minXp-prog.level.minXp)*100)) : 100)+'%"></div>'
    + '</div></div>';

  // Rang de Quiz : la vraie recompense pour les quiz reussis, mise en avant separement du
  // reste de la progression (bien plus parlant qu'un simple chiffre d'XP additionnel).
  var qrank = quizRankFor(quizPerfectCount(state));
  html += '<div class="card" style="margin-bottom:24px;border-color:#5B6FE8;background:linear-gradient(120deg,rgba(91,111,232,0.14),rgba(201,162,75,0.06));text-align:center;padding:20px">'
    + '<div style="font-size:11px;letter-spacing:0.1em;color:#8A8690;margin-bottom:6px">RANG DE QUIZ</div>'
    + '<div style="font-size:36px;margin-bottom:4px">'+qrank.icon+'</div>'
    + '<div class="disp" style="font-size:22px;color:#5B6FE8">'+esc(qrank.name)+'</div>'
    + '<div style="font-size:12px;color:#B7B2AA;margin-top:6px">'+qrank.count+' quiz r\u00E9ussi(s) sans faute'
    + (qrank.next ? (' \u00B7 encore '+(qrank.next.min-qrank.count)+' pour "'+esc(qrank.next.name)+'"') : ' \u00B7 rang maximum atteint !')
    + '</div></div>';

  html += renderTopPicksSection();
  html += renderFavCharSection();

  html += '<div class="disp" style="font-size:20px;color:#C9A24B;margin-bottom:10px">'+'Succès'+' ('+prog.earned.length+'/'+ACHIEVEMENTS.length+')</div>';
  html += '<div class="mcu-ach-grid">' + ACHIEVEMENTS.map(function(a){
    var earned = prog.earned.indexOf(a) !== -1;
    return '<div class="card'+(earned?'':' mcu-ach-locked')+'" title="'+esc(a.desc)+'" style="width:92px;text-align:center">'
      + '<div class="mcu-ach-ico" aria-hidden="true" style="font-size:24px">\uD83C\uDFC6</div><div style="font-size:10px;margin-top:4px">'+esc(a.label)+(earned?'':'<span class="mcu-sr"> (succ\u00E8s \u00E0 d\u00E9bloquer)</span>')+'</div></div>';
  }).join('') + '</div>';

  html += '</div>';
  return html;
}

// Section "Mon Top 5" : selection manuelle et classee par l'utilisateur (remplace l'ancien
// systeme automatique base sur les favoris). Pre-rempli une seule fois avec les favoris /
// contenus les mieux notes deja vus, ensuite entierement gere a la main par l'utilisateur.
function renderTopPicksSection(){
  if (state.profile.topPicks === null) {
    state.profile.topPicks = topFavorites(5).map(function(i){ return i.id; });
    saveState(state);
  }
  var picks = state.profile.topPicks.map(itemById).filter(Boolean);

  var html = '<div class="disp" style="font-size:20px;color:#C9A24B;margin-bottom:4px;text-align:center">'+'Mon Top 5'+'</div>'
    + '<p style="text-align:center;color:#6E7480;font-size:12px;margin-bottom:14px">Choisis et classe tes 5 contenus preferes.</p>';

  if (picks.length < 5) {
    html += '<div class="mcu-search-wrap" style="max-width:420px;margin:0 auto">'
      + '<input data-focus-id="toppick-search" placeholder="'+'Ajouter un film/serie...'+'" value="'+esc(topPickQuery)+'" oninput="mcuSetTopPickQuery(this.value)" autocomplete="off">'
      + (topPickQuery ? '<button type="button" class="mcu-search-clear" onclick="mcuSetTopPickQuery(\'\')">\u2715</button>' : '')
      + '</div>';
    if (topPickQuery) {
      var sugg = searchSuggestions(topPickQuery).filter(function(s){ return s.kind==='media' && state.profile.topPicks.indexOf(s.id)===-1; }).slice(0,5);
      html += sugg.length
        ? '<div class="mcu-suggest" style="position:static;max-width:420px;margin:6px auto 0">' + sugg.map(function(s){
            return '<button type="button" onclick="mcuAddTopPick(\''+s.id+'\')">+ '+esc(s.title)+'<span class="mcu-suggest-sub">'+esc(s.sub)+'</span></button>';
          }).join('') + '</div>'
        : '<p style="text-align:center;color:#5C5964;font-size:12px;margin-top:6px">Aucun résultat.</p>';
    }
  }

  if (picks.length) {
    var podiumSizes = [148, 128, 112, 98, 86];
    html += '<div class="mcu-podium">' + picks.map(function(it, idx){
      var w = podiumSizes[idx] || 80;
      return '<div class="mcu-podium-item" style="width:'+w+'px">'
        + '<div class="mcu-podium-poster-wrap" style="width:'+w+'px" onclick="mcuOpen(\''+it.id+'\')">'
        + '<div class="mcu-podium-rank">'+(idx+1)+'</div>'
        + imgWithFallback(resolvePosterUrl(it.id), '', 'Affiche : '+it.title)
        + '</div>'
        + '<div class="mcu-podium-title">'+esc(it.title)+'</div>'
        + '<div class="mcu-podium-controls">'
        + (idx>0 ? '<button onclick="mcuMoveTopPick(\''+it.id+'\',-1)" title="Monter">\u25C0</button>' : '')
        + '<button onclick="mcuRemoveTopPick(\''+it.id+'\')" title="'+'Retirer'+'" style="color:#E8546B">\u2715</button>'
        + (idx<picks.length-1 ? '<button onclick="mcuMoveTopPick(\''+it.id+'\',1)" title="Descendre">\u25B6</button>' : '')
        + '</div></div>';
    }).join('') + '</div>';
  } else {
    html += '<p style="text-align:center;color:#6E7480;font-size:13px;margin-top:14px">Utilise la recherche ci-dessus pour choisir tes 5 contenus preferes.</p>';
  }
  html += '<div style="margin:28px 0"></div>';
  return html;
}

// Section "Personnage prefere" : choix unique via recherche (meme mecanique que le Top 5),
// affiche en grand avec la couleur/l'icone du personnage, clic pour ouvrir sa fiche complete.
function renderFavCharSection(){
  var ch = state.profile.favChar ? charById(state.profile.favChar) : null;
  var html = '<div class="disp" style="font-size:20px;color:#C9A24B;margin-bottom:4px;text-align:center">'+'Personnage pr\u00E9f\u00E9r\u00E9'+'</div>';

  if (ch) {
    var pal = paletteFor(ch.id);
    var color = ch.color || pal[0];
    var img = cardImageForChar(ch.id);
    html += '<div class="card" style="max-width:380px;margin:14px auto 28px;display:flex;gap:16px;align-items:center;border-color:'+color+';cursor:pointer" onclick="mcuOpenChar(\''+ch.id+'\')">'
      + '<div style="width:64px;height:64px;border-radius:50%;overflow:hidden;flex-shrink:0;position:relative;background:linear-gradient(135deg,'+color+',#08070C)">'+imgWithFallback(img, '', ch.name)+'</div>'
      + '<div style="flex:1;text-align:left;min-width:0">'
      + '<div class="disp" style="font-size:18px;color:'+color+';white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(ch.name)+'</div>'
      + '<div style="font-size:11px;color:#8A8690">'+esc(tierLabel(ch.tier))+'</div></div>'
      + '<button onclick="event.stopPropagation();mcuClearFavChar()" title="Changer" style="color:#9AA0AA;font-size:14px;flex-shrink:0">\u2715</button>'
      + '</div>';
  } else {
    html += '<div class="mcu-search-wrap" style="max-width:380px;margin:0 auto">'
      + '<input data-focus-id="favchar-search" placeholder="Choisis ton personnage pr\u00E9f\u00E9r\u00E9..." value="'+esc(favCharQuery)+'" oninput="mcuSetFavCharQuery(this.value)" autocomplete="off">'
      + (favCharQuery ? '<button type="button" class="mcu-search-clear" onclick="mcuSetFavCharQuery(\'\')">\u2715</button>' : '')
      + '</div>';
    if (favCharQuery) {
      var sugg = searchSuggestions(favCharQuery).filter(function(s){ return s.kind==='character'; }).slice(0,5);
      html += sugg.length
        ? '<div class="mcu-suggest" style="position:static;max-width:380px;margin:6px auto 28px">' + sugg.map(function(s){
            return '<button type="button" onclick="mcuSetFavChar(\''+s.id+'\')">'+esc(s.title)+'</button>';
          }).join('') + '</div>'
        : '<p style="text-align:center;color:#5C5964;font-size:12px;margin:6px 0 28px">Aucun r\u00E9sultat.</p>';
    } else {
      html += '<div style="margin-bottom:28px"></div>';
    }
  }
  return html;
}

function achProg(a){
  var W=function(l){return l.filter(function(i){return state.watched[i.id];}).length;}, M=function(f){return ITEMS.filter(f);}, O=function(u){return OTHER.filter(function(o){return o.universe===u;});};
  var all=ITEMS.concat(OTHER), n=watchedCount(state), c;
  switch(a.id){
    case 'first-step': return [Math.min(n,1),1];
    case '10-down': return [Math.min(n,10),10];
    case '25-down': return [Math.min(n,25),25];
    case 'mcu-veteran': return [Math.min(n,50),50];
    case 'iron-initiative': c=M(function(i){return i.phase===1;}); return [W(c),c.length];
    case 'avengers-assemble': c=['avengers-1','avengers-2','infinity-war','endgame'].map(itemById); return [W(c),c.length];
    case 'infinity-complete': c=M(function(i){return [1,2,3].indexOf(i.phase)>=0;}); return [W(c),c.length];
    case 'multiverse-unlocked': c=M(function(i){return i.phase===4;}); return [Math.min(W(c),1),1];
    case 'post-credit-addict': return sceneStats(state);
    case 'completionist': return [W(ITEMS),ITEMS.length];
    case 'xmen-marathon': c=O('Univers X-Men (Fox)'); return [W(c),c.length];
    case 'spiderverse-complete': c=O('Spider-Verse'); return [W(c),c.length];
    case 'symbiote-saga': c=O("Sony's Spider-Man Universe"); return [W(c),c.length];
    case 'true-completionist': return [W(all),all.length];
    case 'quiz-master': return [quizPerfectCount(state),Object.keys(QUIZZES).length];
  } return null;
}
function renderJourneyView(){
  var prog=computeProgress(state);
  var ALL = ITEMS.concat(OTHER);
  var watchedCount=ALL.filter(function(i){return state.watched[i.id];}).length;
  var pct=Math.round(watchedCount/ALL.length*100);
  var favCount=Object.keys(state.favorites).filter(function(k){return state.favorites[k];}).length;
  var filmsWatched=ALL.filter(function(i){return i.type==='Film' && state.watched[i.id];}).length;
  var totalFilms=ALL.filter(function(i){return i.type==='Film';}).length;
  var seriesWatched=ALL.filter(function(i){return i.type==='Série' && state.watched[i.id];}).length;
  var totalSeries=ALL.filter(function(i){return i.type==='Série';}).length;
  var horsMcuWatched=OTHER.filter(function(i){return state.watched[i.id];}).length;
  var nextUp=ITEMS.filter(function(i){return !state.watched[i.id];}).sort(function(a,b){return a.order-b.order;})[0];

  var html='<div class="wrap"><div class="hero">'
    + '<div class="mono" style="font-size:11px;letter-spacing:0.2em;color:#C9A24B">MON PARCOURS MCU</div>'
    + '<h1 class="disp" style="font-size:38px">NIVEAU '+prog.level.level+' <span class="crimson">'+esc(prog.level.name).toUpperCase()+'</span></h1>';
  html+='<div style="max-width:420px;margin-top:10px">'
    + '<div style="display:flex;justify-content:space-between;font-size:12px;color:#9AA0AA;margin-bottom:4px"><span>'+prog.xp+' XP</span>'+(prog.level.next?('<span>'+prog.xpToNext+' XP avant '+esc(prog.level.next.name)+'</span>'):'<span>Niveau maximum</span>')+'</div>'
    + '<div class="bar-outer"><div class="bar-inner" style="width:'+(prog.level.next? Math.round((prog.xp-prog.level.minXp)/(prog.level.next.minXp-prog.level.minXp)*100):100)+'%"></div></div>'
    + '</div></div>';

  html+='<div class="statbar" style="margin-bottom:24px">'
    + '<div class="statchip"><div class="label">Progression globale (MCU + Hors MCU)</div><div class="val">'+pct+'%</div></div>'
    + '<div class="statchip"><div class="label">Films vus</div><div class="val">'+filmsWatched+'/'+totalFilms+'</div></div>'
    + '<div class="statchip"><div class="label">Séries vues</div><div class="val">'+seriesWatched+'/'+totalSeries+'</div></div>'
    + '<div class="statchip"><div class="label">Hors MCU vus</div><div class="val">'+horsMcuWatched+'/'+OTHER.length+'</div></div>'
    + '<div class="statchip"><div class="label">Favoris</div><div class="val">'+favCount+'</div></div>'
    + '<div class="statchip"><div class="label">MCU vus</div><div class="val">'+ITEMS.filter(function(i){return state.watched[i.id];}).length+'/'+ITEMS.length+'</div></div>'
    + '<div class="statchip"><div class="label">Temps de visionnage*</div><div class="val">'+fmtDuration(ALL.filter(function(i){return state.watched[i.id];}).reduce(function(t,i){return t+(i.duration||0);},0))+'</div></div>'
    + '</div>';

  if(nextUp){
    html+='<div class="card" style="margin-bottom:24px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">'
      + '<div><div style="font-size:11px;color:#9AA0AA">Prochain contenu MCU</div><div class="disp" style="font-size:22px">'+esc(nextUp.title)+'</div></div>'
      + '<button class="btn-cta" onclick="mcuOpen(\''+nextUp.id+'\')">Continuer mon parcours \u2192</button>'
      + '</div>';
  }

  html+='<div class="disp" style="font-size:20px;color:#C9A24B;margin-bottom:8px">Progression par phase</div><div style="margin-bottom:24px">';
  PHASES.forEach(function(p){
    var items=ITEMS.filter(function(i){return i.phase===p.id;});
    var done=items.filter(function(i){return state.watched[i.id];}).length;
    var ppct=items.length?Math.round(done/items.length*100):0;
    var col=phaseColor(p.id);
    html+='<div class="phase-row"><div class="disp" style="width:70px;color:'+col+'">'+p.label+'</div><div class="bar-outer" style="flex:1"><div class="bar-inner" style="width:'+ppct+'%;background:'+col+'"></div></div><div class="mono" style="width:90px;text-align:right;font-size:12px;color:#9AA0AA">'+done+'/'+items.length+' \u00B7 '+ppct+'%'+(ppct===100?' \u2713':'')+'</div></div>';
  });
  html+='</div>';

  html+='<div class="disp" style="font-size:20px;color:#C9A24B;margin-bottom:10px">Achievements</div><div class="grid">';
  ACHIEVEMENTS.forEach(function(a){
    var unlocked=prog.earned.some(function(e){return e.id===a.id;});
    var _p=achProg(a);
    html+='<div class="achv '+(unlocked?'unlocked':'locked')+'"><div class="disp" style="font-size:16px">'+(unlocked?'\uD83C\uDFC6 ':'\uD83D\uDD12 ')+esc(a.label)+'</div><div style="font-size:12px;color:#9AA0AA;margin-top:2px">'+esc(a.desc)+'</div>'
      + (_p ? '<div class="mono" style="font-size:11px;color:#C9A24B;margin-top:8px">'+_p[0]+'/'+_p[1]+'</div><div class="bar-outer" style="height:5px;margin-top:3px"><div class="bar-inner" style="width:'+(_p[1]?Math.round(_p[0]/_p[1]*100):0)+'%"></div></div>' : '')
      + (unlocked && ACH_AUDIO[a.id] ? '<button class="btn" style="margin-top:10px" onclick="mcuReplayAch(\''+a.id+'\')">'+(achPlay.id===a.id ? '\u23F9 Arr\u00EAter' : '\u25B6 R\u00E9\u00E9couter')+'</button>' : '')
      + '</div>';
  });
  html+='</div>'+renderSecretsBlock()+'<p style="font-size:11px;color:#6E7480;margin-top:14px">* Temps cumulé des durées indiquées sur les fiches (pour une série : durée totale approximative de la saison).</p></div>';
  return html;
}

function selectBtnHtml(){ return '<button type="button" class="btn'+(selectMode?' on-fav':'')+'" onclick="mcuToggleSelectMode()">\u2611 Sélection multiple</button>'; }
function visibleIds(){
  if(view==='timeline') return filteredItems().map(function(i){return i.id;});
  var q=(filters.hmQuery||'').toLowerCase(), uni=filters.hmUni||'Tous';
  return OTHER.filter(function(o){ return statusOk(o.id)&&(uni==='Tous'||o.universe===uni)&&(!q||o.title.toLowerCase().indexOf(q)!==-1); }).map(function(o){return o.id;});
}
function bulkBarHtml(){
  var n=Object.keys(bulkSel).length;
  return '<div class="mcu-bulkbar"><span class="mono" style="font-size:12px;color:#E8C468">'+n+' sélectionné'+(n>1?'s':'')+'</span>'
   +'<button class="btn" onclick="mcuBulkAll()">Tout sélectionner</button>'
   +'<button class="btn-cta" style="padding:8px 16px;font-size:13px" onclick="mcuBulkApply(true)"'+(n?'':' disabled')+'>\u2713 Marquer vus</button>'
   +'<button class="btn" onclick="mcuBulkApply(false)"'+(n?'':' disabled')+'>Retirer des vus</button>'
   +'<button class="btn" onclick="mcuToggleSelectMode()">Annuler</button></div>';
}
window.mcuToggleSelectMode=function(){ selectMode=!selectMode; bulkSel={}; withPreservedScroll(function(){ renderApp(); }); };
window.mcuRowClick=function(id){
  if(!selectMode){ window.mcuOpen(id); return; }
  if(bulkSel[id]) delete bulkSel[id]; else bulkSel[id]=true;
  withPreservedScroll(function(){ renderApp(); });
};
window.mcuBulkAll=function(){ var ids=visibleIds(), all=ids.every(function(i){return bulkSel[i];}); bulkSel={}; if(!all){ ids.forEach(function(i){bulkSel[i]=true;}); } withPreservedScroll(function(){ renderApp(); }); };
window.mcuBulkApply=function(flag){
  var ids=Object.keys(bulkSel), skipped=0, changed=0;
  ids.forEach(function(id){
    if(flag && !isReleased(itemById(id))){ skipped++; return; }
    if(!!state.watched[id]!==flag){ state.watched[id]=flag; changed++; }
  });
  var newly=[];
  if(flag){ newly=ACHIEVEMENTS.filter(function(a){return a.check(state)&&!state.seenAchievements[a.id];}); newly.forEach(function(a){state.seenAchievements[a.id]=true;}); }
  saveState(state); bulkSel={}; selectMode=false;
  withPreservedScroll(function(){ renderApp(); });
  showToast(flag?'\u2713':'\u21A9','SÉLECTION MULTIPLE',changed+' contenu'+(changed>1?'s':'')+(flag?' marqué'+(changed>1?'s':'')+' vu'+(changed>1?'s':''):' retiré'+(changed>1?'s':'')+' des vus'),skipped?(skipped+' pas encore sorti(s), ignoré(s).'):'');
  newly.forEach(function(a,i){ setTimeout(function(){ showAchievementToast(a); }, 900+i*550); });
};
var BG_HUE = {1:90, 2:60, 3:30, 4:-10, 5:-30, 6:-130};   // fond violet (~270°) -> rouge (phase 1) ... vert Doom (phase 6)
var bgLast = null;
function bgSet(h){ if(bgLast!==null && Math.abs(bgLast-h)<0.5) return; bgLast=h; var a=document.getElementById('mcu-app'); if(a) a.style.setProperty('--bg-hue', h.toFixed(1)+'deg'); }
function bgTick(){
  if(view!=='timeline'){ bgSet(0); return; }
  var hs=document.querySelectorAll('#mcu-view-root .v-phase-header[data-phase]');
  if(!hs.length){ bgSet(0); return; }
  var ref=window.innerHeight*0.45, cur=-1, i, tops=[];
  for(i=0;i<hs.length;i++){ tops.push(hs[i].getBoundingClientRect().top); if(tops[i]<=ref) cur=i; }
  var H=function(el){ return BG_HUE[parseInt(el.getAttribute('data-phase'),10)] || 0; };
  var h;
  if(cur<0){ var f=Math.max(0,Math.min(1,1-(tops[0]-ref)/window.innerHeight)); h=H(hs[0])*f; }
  else if(cur===hs.length-1){ h=H(hs[cur]); }
  else { var t=Math.max(0,Math.min(1,(ref-tops[cur])/(tops[cur+1]-tops[cur]))); h=H(hs[cur])+(H(hs[cur+1])-H(hs[cur]))*t; }
  bgSet(h);
}
var bgRaf=0; window.addEventListener('scroll', function(){ if(!bgRaf){ bgRaf=requestAnimationFrame(function(){ bgRaf=0; bgTick(); }); } }, {passive:true});
function renderApp(){
  var nav=document.getElementById('mcu-nav-root');
  var v=document.getElementById('mcu-view-root');
  nav.innerHTML = renderNav();
  var html='';
  if(view==='timeline') html=renderTimelineView();
  else if(view==='characters') html=renderCharactersView();
  else if(view==='horsmcu') html=renderHorsMCUView();
  else if(view==='multiverse') html=renderMultiverseView();
  else if(view==='journey') html=renderJourneyView();
  else if(view==='profile') html=renderProfileView();
  v.innerHTML = html;
  setTimeout(bgTick, 0);
  if(selectMode && (view==='timeline'||view==='horsmcu')) v.insertAdjacentHTML('beforeend', bulkBarHtml());
}
function renderModal(){
  var m=document.getElementById('mcu-modal-root');
  // Preserve la position de defilement interne de la fenetre (overlay) : sans ca, chaque
  // question de quiz validee reconstruit toute la modale et renvoie visuellement en haut,
  // ce qui est desagreable quand le quiz est plus bas dans une longue fiche.
  var prevOverlay = m.querySelector('.modal-overlay');
  var prevScrollTop = prevOverlay ? prevOverlay.scrollTop : 0;
  m.innerHTML = currentInfoPanel ? renderInfoModal() : (currentCardId ? renderCardDetailModal() : (currentCharId ? renderCharDetailModal() : (currentItemId ? renderDetailModal() : '')));
  var newOverlay = m.querySelector('.modal-overlay');
  if (newOverlay && prevScrollTop) { newOverlay.scrollTop = prevScrollTop; }
  tickCountdowns();
}
function withPreservedScroll(fn){
  var y = window.scrollY;
  fn();
  window.scrollTo(0, y);
}

window.mcuGoto=function(v){ bulkSel={}; view=v; currentItemId=null; currentCharId=null; currentCardId=null; renderApp(); renderModal(); window.scrollTo({top:0,behavior:'smooth'}); };
// Ouvre la fiche d'un CONTENU (film/serie). Garde-fou : si jamais un ID personnage
// ("char-...") arrivait ici par erreur, itemById() ne le trouvera pas (espace disjoint)
// et la modale ne s'ouvrira simplement pas, plutot que d'afficher la mauvaise fiche.
window.mcuOpen=function(id){ currentItemId=id; currentCharId=null; currentCardId=null; spoilerOn=false; renderModal(); };
window.mcuCloseModal=function(){ currentItemId=null; withPreservedScroll(function(){ renderApp(); renderModal(); }); };
// Ouvre la fiche d'un PERSONNAGE. Garde-fou symetrique : si jamais un ID film/serie
// arrivait ici par erreur, charById() ne le trouvera pas (espace disjoint), la modale
// personnage ne s'ouvrira pas au lieu d'afficher des donnees incoherentes.
window.mcuOpenChar=function(id){ currentCharId=id; currentItemId=null; currentCardId=null; renderModal(); };
