// Inclinaison 3D de la carte (souris au survol, doigt en glissant) avec reflet qui suit l'angle.
window.mcuTilt=function(ev, wrap){
  var box = wrap.querySelector('.mcu-tiltbox'); if (!box) return;
  var r = wrap.getBoundingClientRect(); if (!r.width || !r.height) return;
  var x = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
  var y = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
  var rank = parseInt(box.getAttribute('data-rank') || '0', 10), op = [0.2, 0.32, 0.42, 0.55, 0.7][rank] || 0.2;
  box.style.transition = 'transform .06s linear';
  box.style.transform = 'rotateY(' + (x*24).toFixed(1) + 'deg) rotateX(' + (-y*24).toFixed(1) + 'deg)';
  box.style.setProperty('--sx', ((x+1)*50).toFixed(0) + '%'); box.style.setProperty('--sy', ((y+1)*50).toFixed(0) + '%'); box.style.setProperty('--so', op);
};
window.mcuTiltReset=function(wrap){
  var box = wrap.querySelector('.mcu-tiltbox'); if (!box) return;
  box.style.transition = 'transform .5s ease'; box.style.transform = 'rotateY(0deg) rotateX(0deg)'; box.style.setProperty('--so', 0);
};
window.mcuPackOpen=function(){
  if (!packState || packState.opening) return;
  var firstCard = cardById(packState.ids[0]);
  packState.opening = true; stopLobby();
  var timed = !!(firstCard && RARITY_SFX[firstCard.rarity]);
  // Mythique : son des Pierres d'Infinite des le debut. Commune / Rare / Epique : un seul son pour toute
  // l'ouverture, la carte apparait au time code du son. Legendaire : son de paquet puis revelation classique.
  if (firstCard && firstCard.rarity === 'Mythique') sfxMythic();
  else if (timed) { packState.audio = startRaritySfx(firstCard.rarity); packState.soundStart = Date.now(); }
  else sfxTear();
  renderPack();
  setTimeout(function(){
    if (!packState) return;
    packState.idx = 0; packState.opening = false;
    if (timed) beginTimedReveal(firstCard, true, packState.soundStart);
    renderPack();
    if (!timed) packRevealSound();
  }, 1450);
};
window.mcuPackNext=function(){
  if (!packState) return;
  stopRaritySfx(); packState.audio = null;           // coupe la fin du son precedent
  packState.idx++; packState.waiting = false; packState.timed = false;
  var c = cardById(packState.ids[packState.idx]);
  // Meme logique pour chaque carte suivante.
  if (c && c.rarity === 'Mythique') sfxMythic();
  var timed = !!(c && RARITY_SFX[c.rarity]);
  if (timed) beginTimedReveal(c, false);
  renderPack();
  if (!timed) packRevealSound();
};
window.mcuPackSkip=function(){ if (!packState || !packState.waiting) return; stopRaritySfx(); revealCardNow(packState.token); };
window.mcuPackClose=function(){ stopRaritySfx(); stopLobby(); packState = null; renderPack(); musicSetDuck(false); };
window.mcuToggleSound=function(){
  state.soundOn = !soundOn(); saveState(state);
  if (!soundOn()) { stopRaritySfx(); stopLobby(); }
  else if (packState && packState.idx < 0 && !packState.opening) { startLobby(); }
  if (packState) { renderPack(); } else { withPreservedScroll(function(){ renderApp(); renderModal(); }); }
};

