window.mcuToggleWatched=function(id){
  var _it=itemById(id);
  if(!state.watched[id] && !isReleased(_it)){ showToast('\u23F3','PAS ENCORE SORTI','Impossible de cocher ce contenu','Il n\'est pas encore disponible.'); return; }
  state.watched[id]=!state.watched[id];
  var newlyEarned = [];
  if (state.watched[id]) {
    // On ne detecte/notifie que sur un ajout (pas quand on decoche un "vu" par erreur),
    // en comparant les achievements obtenus avant/apres contre ceux deja notifies.
    var earnedNow = ACHIEVEMENTS.filter(function(a){ return a.check(state); });
    newlyEarned = earnedNow.filter(function(a){ return !state.seenAchievements[a.id]; });
    newlyEarned.forEach(function(a){ state.seenAchievements[a.id] = true; });
  }
  // Le visionnage ne debloque plus aucune carte : seul le quiz parfait le fait.
  saveState(state);
  withPreservedScroll(function(){ renderApp(); renderModal(); });
  newlyEarned.forEach(function(a, i){ setTimeout(function(){ showAchievementToast(a); }, i*550); });
};
