function rerenderPreservingFocus(){
  var active=document.activeElement;
  var focusId = active ? active.getAttribute('data-focus-id') : null;
  var selStart = active && active.selectionStart!=null ? active.selectionStart : null;
  var selEnd = active && active.selectionEnd!=null ? active.selectionEnd : null;
  var y = window.scrollY;
  renderApp();
  window.scrollTo(0, y);
  if (focusId) {
    var el = document.querySelector('[data-focus-id="'+focusId+'"]');
    if (el) {
      el.focus();
      if (selStart!=null && el.setSelectionRange) { try { el.setSelectionRange(selStart, selEnd); } catch(e){} }
    }
  }
}
window.mcuSetFilter=function(k,v){
  // Secrets : un code tape dans une barre de recherche declenche un effet, puis le champ est vide.
  var sid = (k==='query' || k==='cardQuery' || k==='hmQuery') ? secretFromQuery(v) : null;
  if (sid) { v = ''; }
  filters[k]=v;
  rerenderPreservingFocus();
  if (sid) { secretTrigger(sid); }
};
// Vide un champ de recherche via le bouton croix, en gardant le focus dessus.
window.mcuClearFilter=function(k){ window.mcuSetFilter(k, ''); };
// Clic sur une suggestion de la recherche : ouvre directement la fiche correspondante
// (contenu ou personnage) et vide le champ de recherche.
window.mcuSelectSuggestion=function(id, kind, filterKey){
  filters[filterKey] = '';
  if (kind==='character') { window.mcuOpenChar(id); } else { window.mcuOpen(id); }
  renderApp();
};

