function gauntletHtml(o){
  o = o || {}; gauntletPreload();
  var found = STONES.filter(function(st){ return o.all || !!(state.stones && state.stones[st.id]); });
  var meta = JSON.stringify({ all: !!o.all, popId: o.popId || null, seq: !!o.seq });
  var allDone = !o.seq && found.length >= STONES.length;
  var h = '<div class="mcu-gimg" data-o=\'' + meta + '\'><img class="gl" alt="" src="' + gUrl(allDone ? 'full' : 'base') + '" onerror="mcuGFallback(this)">';
  if (o.seq) {
    STONES.forEach(function(st, i){ h += gLayer(st.id, 'in', 'opacity:0;animation-delay:' + (0.3 + i * 0.45).toFixed(2) + 's'); });
    h += gLayer('full', 'fadefull', 'opacity:0;animation-delay:' + (0.3 + STONES.length * 0.45 + 0.5).toFixed(2) + 's');
  } else if (allDone) {
    // tout est trouve : le gant complet, seul (deja affiche ci-dessus)
  } else {
    found.forEach(function(st){ h += gLayer(st.id, o.popId === st.id ? 'in' : '', ''); });
  }
  return h + '</div>';
}
