/* ---- effets ---- */
/* Poussiere grise / noire qui s'envole depuis chaque element qui disparait (calque canvas plein ecran) */
function snapParticles(nodes){
  var old = document.getElementById('mcu-snap-canvas'); if (old && old.parentNode) { old.parentNode.removeChild(old); }
  if (fxReduced()) return;
  var VW = window.innerWidth || 1200, VH = window.innerHeight || 800, dpr = Math.min(2, window.devicePixelRatio || 1);
  var cv = document.createElement('canvas'); cv.id = 'mcu-snap-canvas'; cv.width = Math.round(VW * dpr); cv.height = Math.round(VH * dpr);
  cv.style.cssText = 'position:fixed;left:0;top:0;width:100%;height:100%;z-index:9993;pointer-events:none';
  var ctx = null; try { ctx = cv.getContext('2d'); } catch(e){}
  if (!ctx) return;
  document.getElementById('mcu-app').appendChild(cv); ctx.scale(dpr, dpr);
  var sx = window.scrollX || 0, sy = window.scrollY || 0, parts = [], budget = 3600;
  var PAL = ['#0a0a0b', '#1b1b1e', '#2e2e33', '#55555b', '#7d7d83', '#a8a8ad', '#d2d2d6'];
  nodes.forEach(function(n){
    var r = n.getBoundingClientRect(); if (r.width < 4 || r.height < 4 || r.bottom < -150 || r.top > VH + 150) return;
    var cnt = Math.min(budget, Math.min(320, Math.max(40, Math.round(r.width * r.height / 180)))); budget -= cnt;
    var d = (n.__snapD || 0) * 1000;
    for (var i = 0; i < cnt; i++) {
      parts.push({ x: r.left + sx + Math.random() * r.width, y: r.top + sy + Math.random() * r.height, vx: 25 + Math.random() * 100, vy: -(8 + Math.random() * 65),
        sz: 1.4 + Math.random() * 3.4, life: (2 + Math.random() * 2.6) * 1000, t0: d + Math.random() * 1100, c: PAL[Math.floor(Math.random() * PAL.length)], w: Math.random() * 6.28 });
    }
  });
  var tStart = Date.now(), last = tStart, raf = window.requestAnimationFrame || function(f){ return setTimeout(f, 33); };
  (function frame(){
    var now = Date.now(), dt = Math.min(0.05, (now - last) / 1000), el = now - tStart, alive = false; last = now;
    ctx.clearRect(0, 0, VW, VH);
    var cx = window.scrollX || 0, cy = window.scrollY || 0;
    for (var i = 0; i < parts.length; i++) {
      var q = parts[i], age = el - q.t0;
      if (age < 0) { alive = true; continue; }
      if (age > q.life) continue;
      alive = true; q.w += dt * 3; q.x += (q.vx + Math.sin(q.w) * 18) * dt; q.y += (q.vy + Math.cos(q.w * 0.8) * 10) * dt; q.vy -= dt * 4;
      var k = age / q.life, a = (1 - Math.pow(k, 1.4)) * Math.min(1, age / 150);
      ctx.globalAlpha = a < 0 ? 0 : a; ctx.fillStyle = q.c; ctx.fillRect(q.x - cx - q.sz / 2, q.y - cy - q.sz / 2, q.sz, q.sz);
    }
    ctx.globalAlpha = 1;
    if (alive && cv.parentNode) { raf(frame); } else if (cv.parentNode) { cv.parentNode.removeChild(cv); }
  })();
}
