    var t = now - t0, loader = becoming && t < tA, ph = loader ? 'L' : 'F';
    if (b.__ph !== ph) { b.__ph = ph; b.innerHTML = loader ? SPIN : '<span style="display:inline-block">' + fin + '</span>'; }
